import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
import { TransformControls } from 'three/examples/jsm/controls/TransformControls.js';
import { Line2 } from 'three/examples/jsm/lines/Line2.js';
import { LineMaterial } from 'three/examples/jsm/lines/LineMaterial.js';
import { LineGeometry } from 'three/examples/jsm/lines/LineGeometry.js';
import { Text } from 'troika-three-text';
import { debugLog } from './debugger/debugLog.js';

import GUI from 'lil-gui';

export class CurveEditor {
    constructor(scene, camera, renderer) {
        this.scene = scene;
        this.camera = camera;
        this.renderer = renderer;
        this.domElement = renderer.domElement;

        // State
        this.curves = {};
        this.curveCounter = 0;
        this.activeCurveId = null;

        // Add Undo/Redo Stacks
        this.undoStack = [];
        this.redoStack = [];

        this.pointRad = 25;
        // Shared Geometries & Materials
        this.sphereGeo = new THREE.SphereGeometry(this.pointRad, 8, 8);
        this.pointMaterial = new THREE.MeshBasicMaterial({ color: 0xff0000, transparent: true, opacity: 0.5 });
        // this.lineMaterial = new THREE.LineBasicMaterial({ color: 0x00ff00, linewidth: 15 });
        this.lineMaterial = new LineMaterial({
            color: Math.floor(Math.random() * 0x00ff00),
            linewidth: 6, // in pixels
            worldUnits: false,
        });
        // Setup Systems
        this.initControls();
        this.initRaycaster();
        this.initGUI();
        this.initKeyboard();
        this.initFileUploader();
        // this.toggleAllCurves(false);
    }

    initControls() {
        // We initialize OrbitControls here so the editor can easily disable them during dragging
        this.orbitControls = new OrbitControls(this.camera, this.domElement);
        this.orbitControls.enabled = false;

        this.transformControls = new TransformControls(this.camera, this.domElement);
        // this.scene.add(this.transformControls);

        const gizmo = this.transformControls.getHelper();
        this.scene.add(gizmo);

        this.transformControls.addEventListener('dragging-changed', (event) => {
            this.orbitControls.enabled = !event.value;

            // ADD THIS: Save state right as the user clicks to start dragging
            if (event.value) {
                this.saveState();
            }

            if (event.value) {
                // ALWAYS lock the camera while dragging a point
                this.orbitControls.enabled = false;
            } else {
                // When you let go, restore the camera to whatever the UI toggle is set to
                this.orbitControls.enabled = this.uiParams.enableOrbit;
            }
        });

        this.transformControls.addEventListener('change', () => {
            if (this.activeCurveId !== null) {
                this.updateCurveVisualization(this.activeCurveId);
            }
        });
    }

    initRaycaster() {
        this.raycaster = new THREE.Raycaster();
        this.mouse = new THREE.Vector2();

        window.addEventListener('pointerdown', (event) => {
            // Prevent raycasting if clicking on the lil-gui UI
            if (event.target.closest('.lil-gui')) return;

            this.mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
            this.mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

            this.raycaster.setFromCamera(this.mouse, this.camera);

            const allPoints = Object.values(this.curves).flatMap(c => c.pointMeshes);

            const visiblePoints = Object.values(this.curves)
                .filter(curve => curve.visible)
                .flatMap(curve => curve.pointMeshes);

            const intersects = this.raycaster.intersectObjects(visiblePoints);

            if (intersects.length > 0) {
                const clickedMesh = intersects[0].object;
                this.transformControls.attach(clickedMesh);

                if (clickedMesh.userData.curveId !== this.activeCurveId) {
                    this.setActiveCurve(clickedMesh.userData.curveId);
                }
            }
        });
    }

    initGUI() {
        this.gui = new GUI({ title: 'Curve Editor', closeFolders: true });
        this.gui.domElement.style.left = '0px';
        this.gui.domElement.style.right = 'auto';

        this.uiParams = {
            activeCurve: '',
            createNew: () => this.createCurve(),
            addPoint: () => this.addPointToActiveCurve(),
            visible: true,
            curveType: 'centripetal',
            exportedData: '',
            currentFilename: 'None',
            showAllCurves: false,
            enableOrbit: this.orbitControls.enabled,
        };

        const curvesMaster = this.gui.addFolder('Curves Master');

        curvesMaster.add(this.uiParams, 'createNew').name('Create New Curve');
        // 1. Add the Global Toggle (perhaps near the top)
        curvesMaster.add(this.uiParams, 'showAllCurves')
            .name('👁️ Show All Curves')
            .onChange(v => this.toggleAllCurves(v));


        // Add the toggle and link it directly to the OrbitControls
        curvesMaster.add(this.uiParams, 'enableOrbit')
            .name('🎥 Allow Camera Orbit')
            .onChange(v => {
                this.orbitControls.enabled = v;
            });

        const currentCurve = this.gui.addFolder('Current Curve');

        this.curveSelectController = currentCurve.add(this.uiParams, 'activeCurve', [])
            .name('Active Curve')
            .onChange(v => this.setActiveCurve(v));

        currentCurve.add(this.uiParams, 'addPoint').name('Add Point');

        currentCurve.add(this.uiParams, 'visible').name('Show Curve')
            // .onChange(v => {
            //     if(this.activeCurveId) {
            //         this.curves[this.activeCurveId].line.visible = v;
            //         this.curves[this.activeCurveId].visible = v;
            //     }
            // });
            .listen() // Add .listen() so the global toggle can update this checkbox visually
            .onChange(v => {
                if (this.activeCurveId) {
                    this.setCurveVisibility(this.activeCurveId, v);
                }
            });

        currentCurve.add(this.uiParams, 'curveType', ['centripetal', 'chordal', 'catmullrom'])
            .name('Curve Type')
            .onChange(v => {
                if (this.activeCurveId) {
                    this.curves[this.activeCurveId].type = v;
                    this.updateCurveVisualization(this.activeCurveId);
                }
            });

        this.exportController = currentCurve.add(this.uiParams, 'exportedData').name('Points Data').listen();

        // 2. Create a custom textarea element and style it to match lil-gui
        const textarea = document.createElement('textarea'); ``
        textarea.rows = 6; // Set the visible height
        textarea.style.width = '100%';
        textarea.style.background = 'var(--widget-color)';
        textarea.style.color = 'var(--string-color)';
        textarea.style.border = 'none';
        textarea.style.borderRadius = 'var(--widget-border-radius)';
        textarea.style.padding = '4px';
        textarea.style.fontFamily = 'monospace'; // Better for reading coordinates
        textarea.style.resize = 'vertical'; // Allow the user to drag the height
        textarea.style.boxSizing = 'border-box';
        // 3. Swap the default input with the new textarea in the DOM
        const inputElement = this.exportController.$input;
        inputElement.parentNode.replaceChild(textarea, inputElement);

        currentCurve.add(this.uiParams, 'currentFilename').name('Current File').disable().listen();
        // 4. Re-assign lil-gui's internal reference so .listen() still works
        this.exportController.$input = textarea;

        // this.uiParams.exportJSON = () => this.exportJSON();
        // // Add this right after your 'exportedData' text area
        // this.gui.add(this.uiParams, 'exportJSON').name('📥 Download JSON File');

        // Add some visual padding before the import/save buttons
        // const padding = this.gui.add( {}, '' ).name( '' ).disable();
        // padding.domElement.parentElement.style.height = '10px';

        // Inside initGUI()
        this.uiParams.importJSON = () => this.fileInput.click();

        currentCurve.add(this.uiParams, 'importJSON').name('📤 Import JSON Curve');

        // Inside initGUI()

        // Replace the old export logic with the new save function
        this.uiParams.saveCurve = () => this.saveActiveCurve();

        // Add the button
        currentCurve.add(this.uiParams, 'saveCurve').name('💾 Save Curve As...');

        const stateFolder = this.gui.addFolder('State Functions');
        this.uiParams.undo = () => this.undo();
        stateFolder.add(this.uiParams, 'undo').name('↩ Undo');

        this.uiParams.redo = () => this.redo();
        stateFolder.add(this.uiParams, 'redo').name('↩ Redo');

        this.gui.hide();
    }

    createCurve(initialPoints = [], contentGroup = null, sourceFilename = null, curveId = "", isVisible = false) {
        let id = curveId
        if (!id)
            id = `Curve ${++this.curveCounter}`;
        if (contentGroup == null)
            contentGroup = this.scene;

        if (initialPoints.length === 0) {
            initialPoints = [
                new THREE.Vector3(-2, 0, 0),
                new THREE.Vector3(2, 0, 0)
            ];
        }
        const randomColor = new THREE.Color().setHSL(Math.random(), 1.0, 0.5);
        const randomHexColor = Math.random() * 0xffffff;
        const pointMaterial = this.pointMaterial.clone()
        pointMaterial.color = randomColor;

        const meshes = initialPoints.map(pos => {
            const mesh = new THREE.Mesh(this.sphereGeo, pointMaterial.clone());
            mesh.position.copy(pos);
            mesh.userData = { curveId: id };
            // mesh.material.color = 
            contentGroup.add(mesh);
            return mesh;
        });

        // const lineMaterial = this.lineMaterial.clone();
        // lineMaterial.color = randomHexColor;

        const curveObj = new THREE.CatmullRomCurve3(initialPoints, false, 'centripetal');
        // const lineGeo = new THREE.BufferGeometry();
        const lineGeo = new LineGeometry();
        // const line = new THREE.Line(lineGeo, this.lineMaterial.clone());
        const line = new Line2(lineGeo, this.lineMaterial.clone());

        contentGroup.add(line);

        this.curves[id] = {
            id,
            points: initialPoints,
            pointMeshes: meshes,
            curve3: curveObj,
            line: line,
            visible: true,
            type: 'centripetal',
            contentGroup: contentGroup,
            pointColor: randomColor,
            filename: sourceFilename || `${id.replace(/\s+/g, '_')}.json`
        };

        this.updateDropdown();
        this.updateCurveVisualization(id);
        this.setActiveCurve(id);
        this.updatePointLabels(id);

        this.setCurveVisibility(id, this.uiParams.showAllCurves);
        return id;
    }

    updateCurveVisualization(id) {
        const curveData = this.curves[id];
        if (!curveData || !curveData.visible) return;

        const positions = curveData.pointMeshes.map(mesh => mesh.position);
        curveData.curve3.points = positions;
        curveData.curve3.curveType = curveData.type;

        const curvePoints = curveData.curve3.getPoints(50);
        curveData.line.geometry.setFromPoints(curvePoints);

        if (id === this.activeCurveId) {
            this.uiParams.exportedData = JSON.stringify(positions.map(p => [
                Number(p.x.toFixed(2)),
                Number(p.y.toFixed(2)),
                Number(p.z.toFixed(2))
            ]));
        }
    }

    addPointToActiveCurve() {
        if (!this.activeCurveId) return;
        this.saveState(); // ADD THIS HERE

        const curveData = this.curves[this.activeCurveId];

        const lastMesh = curveData.pointMeshes[curveData.pointMeshes.length - 1];
        const newPos = lastMesh ? lastMesh.position.clone().add(new THREE.Vector3(1, 0, 0)) : new THREE.Vector3(0, 0, 0);

        const newMesh = new THREE.Mesh(this.sphereGeo, lastMesh.material.clone());
        newMesh.position.copy(newPos);
        newMesh.userData = { curveId: this.activeCurveId };
        curveData.contentGroup.add(newMesh);

        curveData.pointMeshes.push(newMesh);
        this.updateCurveVisualization(this.activeCurveId);
        this.updatePointLabels(this.activeCurveId);
    }

    setActiveCurve(id) {
        this.activeCurveId = id;
        this.transformControls.detach();

        Object.values(this.curves).forEach(c => {
            c.line.material.color.setHex(c.id === id ? 0x00ff00 : 0x444444);
        });

        if (id) {
            this.uiParams.activeCurve = id;
            this.uiParams.curveType = this.curves[id].type;
            this.uiParams.visible = this.curves[id].visible;
            this.uiParams.currentFilename = this.curves[id].filename || 'Unsaved.json';
            this.updateCurveVisualization(id);
        } else {
            // ADD THIS: Clear the filename if no curves are active
            this.uiParams.currentFilename = 'None';
        }
    }

    updateDropdown() {
        if (this.curveSelectController) {
            this.curveSelectController = this.curveSelectController.options(Object.keys(this.curves));
        }
    }

    updatePointLabels(curveId) {
        const curveData = this.curves[curveId];
        if (!curveData) return;

        curveData.pointMeshes.forEach((mesh, index) => {
            let textMesh = mesh.userData.labelMesh;

            // If the text mesh doesn't exist on this point yet, create it
            if (!textMesh) {
                textMesh = new Text();
                textMesh.fontSize = 25;
                textMesh.position.set(0, this.pointRad + 5, 0); // Float slightly above the sphere
                textMesh.color = 0x000000;
                textMesh.anchorX = 'center';
                textMesh.anchorY = 'bottom';

                // Optional: Give it a dark outline so it's readable on any background
                textMesh.outlineWidth = 0.02;
                textMesh.outlineColor = 0x000000;

                mesh.add(textMesh);
                mesh.userData.labelMesh = textMesh;
            }

            // Update the number
            textMesh.text = index.toString();

            // CRITICAL: Troika requires you to call sync() after updating properties
            textMesh.sync();
        });
    }

    deleteSelectedPoint() {
        // Get the currently selected point
        const selectedMesh = this.transformControls.object;
        if (!selectedMesh) return; // Exit if nothing is selected

        this.saveState(); // ADD THIS HERE

        const curveId = selectedMesh.userData.curveId;
        const curveData = this.curves[curveId];

        // Safety check: A curve needs at least 2 points
        if (curveData.pointMeshes.length <= 2) {
            console.warn("Cannot delete: A curve must have at least 2 points.");
            return;
        }

        // Find the specific point in our array
        const index = curveData.pointMeshes.indexOf(selectedMesh);
        if (index === -1) return;

        // 1. Detach the controls before we delete the object
        this.transformControls.detach();

        // 2. Remove the mesh from the scene
        curveData.contentGroup.remove(selectedMesh);

        // 3. Clean up the Troika text mesh from memory
        if (selectedMesh.userData.labelMesh) {
            selectedMesh.remove(selectedMesh.userData.labelMesh);
            selectedMesh.userData.labelMesh.dispose();
        }

        // 4. Remove the point from our data array
        curveData.pointMeshes.splice(index, 1);

        // 5. Update the visual line and recalculate the remaining index numbers
        this.updateCurveVisualization(curveId);
        this.updatePointLabels(curveId);
    }

    initKeyboard() {
        window.addEventListener('keydown', (event) => {
            // Check if the user is typing inside a lil-gui input box (like the export textarea)
            // We don't want to delete a 3D point when they are just pressing backspace in a text field
            if (event.target.tagName.toLowerCase() === 'input' ||
                event.target.tagName.toLowerCase() === 'textarea') {
                return;
            }

            // Undo: Ctrl + Z  (or Cmd + Z on Mac)
            if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'z' && !event.shiftKey) {
                event.preventDefault(); // Stop browser default behavior
                this.undo();
            }

            // Redo: Ctrl + Y OR Ctrl + Shift + Z
            if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'y' ||
                ((event.ctrlKey || event.metaKey) && event.shiftKey && event.key.toLowerCase() === 'z')) {
                event.preventDefault();
                this.redo();
            }

            if (event.key === 'Delete' || event.key === 'Backspace') {
                this.deleteSelectedPoint();
            }
        });
    }
    // Call this inside your main requestAnimationFrame loop
    update() {
        if (!this.activeCurveId) return;

        const curveData = this.curves[this.activeCurveId];
        if (!curveData) return;

        // Make all text labels perfectly face the camera
        curveData.pointMeshes.forEach(mesh => {
            if (mesh.userData.labelMesh) {
                mesh.userData.labelMesh.quaternion.copy(this.camera.quaternion);
            }
        });
    }

    exportJSON() {
        if (!this.activeCurveId) {
            console.warn("No active curve to export.");
            return;
        }

        const curveData = this.curves[this.activeCurveId];
        // Convert Vector3 objects into raw arrays: [[x, y, z], [x, y, z]]
        const positions = curveData.pointMeshes.map(mesh => [
            Number(mesh.position.x.toFixed(3)),
            Number(mesh.position.y.toFixed(3)),
            Number(mesh.position.z.toFixed(3))
        ]);

        // Create a Blob containing the formatted JSON string
        const jsonString = JSON.stringify(positions, null, 2);
        const blob = new Blob([jsonString], { type: "application/json" });
        const url = URL.createObjectURL(blob);

        // Create a temporary link element to trigger the download
        const link = document.createElement('a');
        link.href = url;
        // Name the file based on the curve ID (e.g., "Curve_1_points.json")
        link.download = `${this.activeCurveId.replace(/\s+/g, '_')}_points.json`;

        document.body.appendChild(link);
        link.click();

        // Cleanup
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    }

    parseCurveJSON(jsonString) {
        try {
            const rawData = JSON.parse(jsonString);

            if (!Array.isArray(rawData)) {
                throw new Error("JSON root must be an array of points.");
            }

            const vectorArray = rawData.map(point => {
                // Handle array format: [x, y, z]
                if (Array.isArray(point) && point.length >= 3) {
                    return new THREE.Vector3(point[0], point[1], point[2]);
                }
                // Handle object format: {x: 1, y: 2, z: 3}
                else if (point && point.x !== undefined && point.y !== undefined && point.z !== undefined) {
                    return new THREE.Vector3(point.x, point.y, point.z);
                }
                throw new Error("Unrecognized point format.");
            });

            return vectorArray;

        } catch (error) {
            console.error("Failed to parse JSON curve data:", error);
            return null;
        }
    }

    initFileUploader() {
        // Create a hidden file input element
        this.fileInput = document.createElement('input');
        this.fileInput.type = 'file';
        this.fileInput.accept = '.json';
        this.fileInput.style.display = 'none';
        document.body.appendChild(this.fileInput);

        // Listen for when the user selects a file
        this.fileInput.addEventListener('change', (event) => {
            const file = event.target.files[0];
            if (!file) return;

            const reader = new FileReader();
            reader.onload = (e) => {
                const vectorArray = this.parseCurveJSON(e.target.result);
                if (vectorArray && vectorArray.length >= 2) {
                    // Create a new curve using the imported points!
                    this.createCurve(vectorArray, this.scene, file.name);
                } else {
                    alert("Invalid curve data. Ensure the file contains at least 2 points.");
                }
            };

            reader.readAsText(file);

            // Reset the input so the same file can be uploaded again if needed
            this.fileInput.value = '';
        });
    }

    /**
     * Fetches a JSON file from a URL/path and creates a curve.
     * @param {string} filepath - The path to the JSON file (e.g., '/curves/level1.json')
     * @returns {Promise<string|null>} The ID of the newly created curve, or null if it failed.
     */
    async loadCurveFromPath(filepath, curveName = "", debug = true) {
        try {
            // 1. Fetch the file from the network/local server
            const response = await fetch(filepath);

            // 2. Check if the fetch was successful (status 200-299)
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }

            // 3. Extract the text content
            const jsonText = await response.text();

            // 4. Parse it using your existing helper method
            const vectorArray = this.parseCurveJSON(jsonText);

            // 5. Create the curve if the data is valid
            if (vectorArray && vectorArray.length >= 2) {
                const filename = filepath.split('/').pop();
                const newCurveId = this.createCurve(vectorArray, this.scene, filename, curveName);
                debugLog(`Successfully loaded curve from ${filepath}`);
                return newCurveId;
            } else {
                console.warn(`File at ${filepath} did not contain valid curve data.`);
                return null;
            }


        } catch (error) {
            console.error(`Failed to load curve from path: ${filepath}`, error);
            return null;
        }
    }

    async saveActiveCurve() {
        if (!this.activeCurveId) {
            console.warn("No active curve to save.");
            return;
        }

        const curveData = this.curves[this.activeCurveId];

        // 1. Format the data to JSON
        const positions = curveData.pointMeshes.map(mesh => [
            Number(mesh.position.x.toFixed(3)),
            Number(mesh.position.y.toFixed(3)),
            Number(mesh.position.z.toFixed(3))
        ]);
        const jsonString = JSON.stringify(positions, null, 2);

        // 2. Try using the modern File System Access API
        try {
            if ('showSaveFilePicker' in window) {
                // This opens the OS "Save As" window
                const fileHandle = await window.showSaveFilePicker({
                    suggestedName: curveData.filename,
                    types: [{
                        description: 'JSON File',
                        accept: { 'application/json': ['.json'] },
                    }],
                });

                // Write the file to the chosen destination
                const writable = await fileHandle.createWritable();
                await writable.write(jsonString);
                await writable.close();

                // Update our state in case the user changed the filename in the dialog!
                curveData.filename = fileHandle.name;
                debugLog(`Successfully saved as ${fileHandle.name}`);

            } else {
                // 3. Fallback for browsers that don't support the API (Firefox/Safari)
                const blob = new Blob([jsonString], { type: "application/json" });
                const url = URL.createObjectURL(blob);
                const link = document.createElement('a');
                link.href = url;
                link.download = curveData.filename; // Use the tracked filename

                document.body.appendChild(link);
                link.click();

                document.body.removeChild(link);
                URL.revokeObjectURL(url);
                debugLog(`Downloaded ${curveData.filename} via fallback method.`);
            }
        } catch (error) {
            // If the user clicks "Cancel" on the file dialog, it throws an AbortError.
            // We can safely ignore that, but log other actual errors.
            if (error.name !== 'AbortError') {
                console.error("Failed to save the file:", error);
            }
        }
    }



    toggleAllCurves(isVisible) {
        Object.values(this.curves).forEach(curveData => {
            // Update our internal state
            curveData.visible = isVisible;

            // Toggle the line visibility
            curveData.line.visible = isVisible;

            // Toggle the spheres and their text labels
            curveData.pointMeshes.forEach(mesh => {
                mesh.visible = isVisible;
                if (mesh.userData.labelMesh) {
                    mesh.userData.labelMesh.visible = isVisible;
                }
            });
        });

        // Keep the individual active curve's UI toggle in sync
        if (this.activeCurveId) {
            this.uiParams.visible = isVisible;
        }
    }

    setCurveVisibility(curveId, isVisible) {
        const curveData = this.curves[curveId];
        if (!curveData) return;

        curveData.visible = isVisible;
        curveData.line.visible = isVisible;

        curveData.pointMeshes.forEach(mesh => {
            mesh.visible = isVisible;
            if (mesh.userData.labelMesh) {
                mesh.userData.labelMesh.visible = isVisible;
            }
        });
    }

    //#region States

    // Helper to get a clean copy of the current active curve's points
    getCurrentPositions() {
        if (!this.activeCurveId) return [];
        return this.curves[this.activeCurveId].pointMeshes.map(m => m.position.clone());
    }

    // Call this RIGHT BEFORE any action happens
    saveState() {
        if (!this.activeCurveId) return;

        // Push the current state to the undo stack
        this.undoStack.push(this.getCurrentPositions());

        // Clear the redo stack because we branched off into a new timeline
        this.redoStack = [];

        // Optional: Limit history to 50 steps to prevent memory leaks over long sessions
        if (this.undoStack.length > 50) this.undoStack.shift();
    }

    applySavedPositions(positions) {
        if (!this.activeCurveId || !positions) return;

        this.transformControls.detach(); // Safety detach
        const curveData = this.curves[this.activeCurveId];

        // 1. Sync the number of 3D spheres
        // If the snapshot has MORE points, create new spheres
        while (curveData.pointMeshes.length < positions.length) {
            const pMaterial = this.pointMaterial.clone();
            pMaterial.color = curveData.pointColor;
            const newMesh = new THREE.Mesh(this.sphereGeo, pMaterial.clone());
            newMesh.userData = { curveId: this.activeCurveId };
            curveData.contentGroup.add(newMesh);
            curveData.pointMeshes.push(newMesh);
        }
        // If the snapshot has FEWER points, delete the extra spheres
        while (curveData.pointMeshes.length > positions.length) {
            const meshToRemove = curveData.pointMeshes.pop();
            curveData.contentGroup.remove(meshToRemove);
            if (meshToRemove.userData.labelMesh) {
                meshToRemove.remove(meshToRemove.userData.labelMesh);
                meshToRemove.userData.labelMesh.dispose();
            }
        }

        // 2. Move existing spheres to the snapshot's coordinates
        for (let i = 0; i < positions.length; i++) {
            curveData.pointMeshes[i].position.copy(positions[i]);
        }

        // 3. Update the visual line and text labels
        this.updateCurveVisualization(this.activeCurveId);
        this.updatePointLabels(this.activeCurveId);
    }

    undo() {
        if (this.undoStack.length === 0) return;
        // 1. Save where we are right now into the Redo stack
        this.redoStack.push(this.getCurrentPositions());
        // 2. Pop the last state and apply it
        const previousState = this.undoStack.pop();
        this.applySavedPositions(previousState);
    }

    redo() {
        if (this.redoStack.length === 0) return;
        // 1. Save where we are right now into the Undo stack
        this.undoStack.push(this.getCurrentPositions());
        // 2. Pop the next state and apply it
        const nextState = this.redoStack.pop();
        this.applySavedPositions(nextState);
    }
    //#endregion
}