import * as THREE from 'three';
import { Text, getSelectionRects } from 'troika-three-text'

import gsap from "gsap"
import { debugLog } from "../../../debugger/debugLog.js";
import { COLORS } from '../../../siteData.js';

export default async function section5Back(animManager) {

    debugLog("Section 5", "sec5_debug");

    const sectionDuration = 5;
    const butterflyPath = "paths/butterflySec5.json";

    animManager.section5BackTl = gsap.timeline({ paused: animManager.typeSectional })

    const phasingData = { progress: 0 };

    // moon 
    animManager.section5BackTl
        .to(phasingData, {
            progress: sectionDuration, // Animate from 0 to 1
            duration: sectionDuration,
            onStart: () => {
                debugLog("moon phase start time " + animManager.section5BackTl.time(), "sec5_bck");
            },
            onUpdate: () => {
                animManager.moonMaterial.uniforms.uTime.value = animManager.moonPhasingData.progress - phasingData.progress; // One full rotation for the phase cycle            
            },
            onComplete: () => {
                animManager.moonPhasingData.progress = animManager.moonPhasingData.progress - phasingData.progress;
                animManager.autoMoon = !animManager.autoMoon;
            }
        }, 0);

    animManager.section5BackTl.to(animManager.inMemoryText, {
        fillOpacity: 0,      // Fade in
        duration: 2.5,
        ease: "power2.out",
        onStart: () => {
            debugLog("memory1 start time " + animManager.section5BackTl.time(), "sec5_bck");
        },
    }, 0)

    animManager.section5BackTl.to(animManager.inMemoryText.position, {
        y: animManager.inMemoryText.position.y - (20 * animManager.scaleFactorVec.y),                // Float up to y: 0
        duration: 2.5,
        ease: "back.out(1.5)", // A slight overshoot for a cool floating effect

        onStart: () => {
            debugLog("memory2 start time " + animManager.section5BackTl.time(), "sec5_bck");
        },
    }, "<");

    const butterflyCurveId = await animManager.curveEditor.loadCurveFromPath(butterflyPath, "bfly-sec5-bck");
    const butterflyCurve1 = animManager.curveEditor.curves[butterflyCurveId].curve3;

    const butterflyFlightData = { progress: 1 };
    animManager.section5BackTl.to(butterflyFlightData, {
        progress: 0,
        duration: 3,
        ease: "sine.inOut",

        onStart: () => {
            debugLog("bfly start time " + animManager.section5BackTl.time(), "sec5_bck");
            animManager.cat.enabled(true);
            animManager.cat.enableFollowBehavior(null, false);
        },

        onUpdate: () => {
            if (butterflyFlightData.progress < 0)
                return;
            let position = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress, 0, 0);
            animManager.butterfly.position.copy(position);
            if (butterflyFlightData.progress + 0.01 < 1) {
                let lookAtPosition = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress + 0.01, 0, 0);
                animManager.butterfly.lookAt(lookAtPosition);
            }
        }
    }, 3);

    animManager.section5BackTl.to(animManager.grassMesh.grassMaterial.uniforms.uColorRadii.value, {
        [1]: 0.0, // Your target full size
        duration: 1,
        ease: "back.out(1.2)",
        onStart: () => {
            debugLog("grass4 start time " + animManager.section5BackTl.time(), "sec5_bck");
        },
    }, ">");

    animManager.section5BackTl.to(animManager.grassMesh.grassMaterial.uniforms.uColorRadii.value, {
        [0]: 0.0, // Your target full size
        duration: 1,
        ease: "back.out(1.2)",
        onStart: () => {
            debugLog("grass3 start time " + animManager.section5BackTl.time(), "sec5_bck");
        },
    }, "<");

    animManager.section5BackTl.to(animManager.grassMesh.grassMaterial.uniforms.uColorIntensities.value, {
        [0]: 0.0,
        duration: 1,
        ease: "power2.out",
        onStart: () => {
            debugLog("grass1 start time " + animManager.section5BackTl.time(), "sec5_bck");
        },
    }, "<");
    animManager.section5BackTl.to(animManager.grassMesh.grassMaterial.uniforms.uColorIntensities.value, {
        [1]: 0.0,
        duration: 1,
        ease: "power2.out",
        onStart: () => {
            debugLog("grass2 start time " + animManager.section5BackTl.time(), "sec5_bck");
        },
    }, "<");

    animManager.section5BackTl
        .to(animManager.backgroundMesh.rotation, {
            x: 0,
            duration: 3,
            ease: "power2.in",
            onStart: () => {
                debugLog("fall start time " + animManager.section5BackTl.time(), "sec5_bck");
            },
        }, ">")

    const targetTextColor = new THREE.Color(COLORS.text);

    animManager.section5BackTl.to(animManager.siteNavAboutTxt.material.color, {
        r: targetTextColor.r,
        g: targetTextColor.g,
        b: targetTextColor.b,
        duration: 0.8,
        ease: "bounce.out(1.5)"
    }, 0)
        .to(animManager.siteNavWorkTxt.material.color, {
            r: targetTextColor.r,
            g: targetTextColor.g,
            b: targetTextColor.b,
            duration: 0.8,
            ease: "bounce.out(1.5)"
        }, "<")
        .to(animManager.siteNavTestimonialsTxt.material.color, {
            r: targetTextColor.r,
            g: targetTextColor.g,
            b: targetTextColor.b,
            duration: 0.8,
            ease: "bounce.out(1.5)"
        }, "<")
        .to(animManager.siteNavAfterlifeTxt.material.color, {
            r: targetTextColor.r,
            g: targetTextColor.g,
            b: targetTextColor.b,
            duration: 0.8,
            ease: "bounce.out(1.5)"
        }, "<")
        .to(animManager.siteNavContactTxt.material.color, {
            r: targetTextColor.r,
            g: targetTextColor.g,
            b: targetTextColor.b,
            duration: 0.8,
            ease: "bounce.out(1.5)"
        }, "<")
        .to(animManager.siteNavUnderLine.material.color, {
            r: targetTextColor.r,
            g: targetTextColor.g,
            b: targetTextColor.b,
            duration: 0.8,
            ease: "bounce.out(1.5)"
        }, "<")



    debugLog("Section 5 end", "sec5_debug");
}