import * as THREE from 'three';
import gsap from 'gsap';
import { Z_LAYERS } from '../siteData.js';
import snakeVertSource from './glsl/snake-flatten.vert.glsl?raw';
import snakeFrag from './glsl/snake-flatten.frag.glsl';

export class ShaderSnake {
   
    constructor(scene, options = {}) {
        this.scene = scene;

        this.numSegments = options.numSegments || 120;
        this.numSegments = Math.max(this.numSegments, 100); // Cap segments for performance
        this.radius = options.radius || 10;
        this.color = options.color || 0x000000;
        
        // Target silhouette configuration (supports options.silhouetteOptions as passed in main.js)
        const silOpts = options.silhouetteOptions || {};
        const silWidth = silOpts.width || (options.manSize ? options.manSize.x : this.radius * 6);
        const silHeight = silOpts.height || (options.manSize ? options.manSize.y : this.radius * 15);
        this.manSize = new THREE.Vector2(silWidth, silHeight);
        
        this.manPosition = options.manPosition 
            ? options.manPosition.clone() 
            : (silOpts.position ? silOpts.position.clone() : new THREE.Vector3(0, 0, 0));

        this.anchorY = silOpts.anchorY !== undefined ? silOpts.anchorY : 0.0;
        this.isAlpha = silOpts.isAlpha !== undefined ? (silOpts.isAlpha ? 1.0 : 0.0) : 1.0;
        
        const cutoff = options.silhouetteCutoff !== undefined 
            ? options.silhouetteCutoff 
            : (silOpts.threshold !== undefined ? silOpts.threshold / 255.0 : 0.15);
        this.silhouetteCutoff = cutoff;

        this.transitionWiggle = options.transitionWiggle !== undefined ? options.transitionWiggle : 1.0;
        this.silhouetteTexture = null;

        // A far-off position, to match the butterfly's starting point and keep the snake off-screen initially.
        this.initialPosition = options.startPos || new THREE.Vector3(913.2, 352.4, 1);

        // Arrays to store the spine positions (Logic only)
        this.spinePositions = new Float32Array(this.numSegments * 3);
        this.spineTarget = []; 
        
        // For following at a distance
        this.lastTargetPosition = this.initialPosition.clone();
        this.targetVelocity = new THREE.Vector3();
        
        this.morphTl = null;
        this.morphVal = 0.0; 
        this.init();        

        // Load silhouette texture if provided in options (supports silhouetteImage or silhouetteTexture)
        const silSource = options.silhouetteImage || options.silhouetteTexture;
        if (silSource) {
            this.setSilhouette(silSource);
        }
    }

    init() {
        // 1. Init Logic Points (Straight line initially)
        const startSpacing = this.radius * 0.5;
        for (let i = 0; i < this.numSegments; i++) {
            const zPos = i * startSpacing;
            
            // Initialize each spine segment starting from the far-off initial position.
            const point = this.initialPosition.clone().add(new THREE.Vector3(0, 0, zPos));
            this.spineTarget.push(point);
            this.updateSpineUniform(i, point.x, point.y, point.z);
        }

        // 2. The Geometry
        // A cylinder where position.z goes from 0.0 (head) to 1.0 (tail)
        const geometry = new THREE.CylinderGeometry(this.radius, this.radius, 1, 32, this.numSegments, true);
        
        // Rotate geometry so it lies along Z axis
        geometry.rotateX(-Math.PI / 2);  
        // Shift so it starts at 0 and goes to 1
        geometry.translate(0, 0, 0.5); 

        const snakeVert = snakeVertSource.replace(
            /NUM_SEGMENTS/g,
            String(this.numSegments)
        );

        // Shared progress uniform object so uProgress & uMorphProgress both point to the same ref
        const progressUniform = { value: 0.0 };

        // 3. The Custom Shader Material with Morphing & Flattening
        const material = new THREE.ShaderMaterial({
            uniforms: {
                uTime: { value: 0 },
                uColor: { value: new THREE.Color(this.color) },
                uSpine: { value: this.spinePositions },
                
                // Morphing uniforms (both names supported for flexibility)
                uProgress: progressUniform,      // 0.0 = Snake, 1.0 = Standing Man Silhouette
                uMorphProgress: progressUniform, // Alias for GSAP convenience
                uManPosition: { value: this.manPosition },
                uManSize: { value: this.manSize },
                uAnchorY: { value: this.anchorY },
                uRadius: { value: this.radius },
                uTransitionWiggle: { value: this.transitionWiggle },
                
                // Texture & Cutout uniforms
                uSilhouetteTexture: { value: null },
                uHasSilhouette: { value: 0.0 }, // Falls back to procedural man silhouette if 0.0
                uIsAlpha: { value: this.isAlpha },
                uSilhouetteCutoff: { value: this.silhouetteCutoff }
            },
            vertexShader: snakeVert,
            fragmentShader: snakeFrag,
            side: THREE.DoubleSide,
            transparent: true,
            depthWrite: true,
        });

        this.mesh = new THREE.Mesh(geometry, material);
        this.mesh.frustumCulled = false;
        this.scene.add(this.mesh);
    }

    /**
     * Sets or loads the silhouette texture for the standing man.
     * @param {THREE.Texture|string} textureOrUrl - A THREE.Texture or image URL path
     */
    setSilhouette(textureOrUrl) {
        if (!textureOrUrl) return;

        if (typeof textureOrUrl === 'string') {
            const loader = new THREE.TextureLoader();
            loader.load(textureOrUrl, (texture) => {
                texture.wrapS = THREE.ClampToEdgeWrapping;
                texture.wrapT = THREE.ClampToEdgeWrapping;
                texture.minFilter = THREE.LinearFilter;
                texture.magFilter = THREE.LinearFilter;
                
                this.silhouetteTexture = texture;
                if (this.mesh && this.mesh.material) {
                    this.mesh.material.uniforms.uSilhouetteTexture.value = texture;
                    this.mesh.material.uniforms.uHasSilhouette.value = 1.0;
                    this.mesh.material.uniforms.uIsAlpha.value = this.isAlpha;
                    this.mesh.material.needsUpdate = true;
                }
            });
        } else if (textureOrUrl.isTexture) {
            this.silhouetteTexture = textureOrUrl;
            if (this.mesh && this.mesh.material) {
                this.mesh.material.uniforms.uSilhouetteTexture.value = textureOrUrl;
                this.mesh.material.uniforms.uHasSilhouette.value = 1.0;
                this.mesh.material.uniforms.uIsAlpha.value = this.isAlpha;
                this.mesh.material.needsUpdate = true;
            }
        }
    }

    /**
     * Updates placement and dimensions of the standing man.
     * @param {THREE.Vector3} position - World position for the man's feet
     * @param {THREE.Vector2} [size] - Width and height of the silhouette
     */
    setManPlacement(position, size) {
        if (position) {
            this.manPosition.copy(position);
            this.mesh.material.uniforms.uManPosition.value.copy(position);
        }
        if (size) {
            this.manSize.copy(size);
            this.mesh.material.uniforms.uManSize.value.copy(size);
        }
    }

    /**
     * Set morph progress manually [0.0 = snake, 1.0 = man silhouette]
     * @param {number} progress 
     */
    setMorphProgress(progress) {
        if (this.mesh && this.mesh.material) {
            this.mesh.material.uniforms.uProgress.value = THREE.MathUtils.clamp(progress, 0.0, 1.0);
        }
    }

    /**
     * Get current morph progress
     * @returns {number}
     */
    getMorphProgress() {
        return this.mesh?.material?.uniforms?.uProgress?.value ?? 0.0;
    }

    /**
     * Smoothly morph snake into standing man silhouette (reversible)
     * Supports both:
     *   morphToMan(2.5, "power2.inOut", onComplete)
     *   morphToMan({ position, size, duration: 2.5, ease: "power2.inOut", onComplete })
     * @param {number|Object} durationOrOptions
     * @param {string} [ease="power2.inOut"]
     * @param {Function} [onComplete=null]
     * @returns {gsap.core.Tween}
     */
    morphToMan(durationOrOptions = 2.5, ease = "power2.inOut", onComplete = null) {
        let duration = 2.5;
        let easing = ease;
        let callback = onComplete;

        if (typeof durationOrOptions === 'object' && durationOrOptions !== null) {
            duration = durationOrOptions.duration !== undefined ? durationOrOptions.duration : 2.5;
            easing = durationOrOptions.ease || "power2.inOut";
            callback = durationOrOptions.onComplete || null;

            if (durationOrOptions.position) {
                this.setManPlacement(durationOrOptions.position, durationOrOptions.size);
            }
        } else if (typeof durationOrOptions === 'number') {
            duration = durationOrOptions;
        }

        if (this.morphTl) this.morphTl.kill();
        this.morphTl = gsap.to(this.mesh.material.uniforms.uProgress, {
            value: 1.0,
            duration,
            ease: easing,
            onComplete: callback
        });
        return this.morphTl;
    }

    /**
     * Smoothly morph standing man silhouette back into snake (reversible)
     * Supports both:
     *   morphToSnake(2.5, "power2.inOut", onComplete)
     *   morphToSnake({ duration: 2.5, ease: "power2.inOut", onComplete })
     * @param {number|Object} durationOrOptions
     * @param {string} [ease="power2.inOut"]
     * @param {Function} [onComplete=null]
     * @returns {gsap.core.Tween}
     */
    morphToSnake(durationOrOptions = 2.5, ease = "power2.inOut", onComplete = null) {
        let duration = 2.5;
        let easing = ease;
        let callback = onComplete;

        if (typeof durationOrOptions === 'object' && durationOrOptions !== null) {
            duration = durationOrOptions.duration !== undefined ? durationOrOptions.duration : 2.5;
            easing = durationOrOptions.ease || "power2.inOut";
            callback = durationOrOptions.onComplete || null;
            
        } else if (typeof durationOrOptions === 'number') {
            duration = durationOrOptions;
        }

        if (this.morphTl) this.morphTl.kill();
        this.morphTl = gsap.to(this.mesh.material.uniforms.uProgress, {
            value: 0.0,
            duration,
            ease: easing,
            onComplete: callback
        });
        return this.morphTl;
    }

    toggleMorph(durationOrOptions = 2.5, ease = "power2.inOut", onComplete = null) {
        let duration = 2.5;
        let easing = ease;
        let callback = onComplete;

        if (typeof durationOrOptions === 'object' && durationOrOptions !== null) {
            duration = durationOrOptions.duration !== undefined ? durationOrOptions.duration : 2.5;
            easing = durationOrOptions.ease || "power2.inOut";
            callback = durationOrOptions.onComplete || null;
        } else if (typeof durationOrOptions === 'number') {
            duration = durationOrOptions;
        }

        if (this.morphTl) this.morphTl.kill();
        if(this.morphVal == 0) // going to man 
        {
            if (durationOrOptions.position) {
                this.setManPlacement(durationOrOptions.position, durationOrOptions.size);
            }
            this.morphVal = 1;
        }            
        else
            this.morphVal = 0;
        this.morphTl = gsap.to(this.mesh.material.uniforms.uProgress, {
            value: this.morphVal,
            duration,
            ease: easing,
            onComplete: callback
        });
        return this.morphTl;
    }

    updateSpineUniform(index, x, y, z) {
        this.spinePositions[index * 3] = x;
        this.spinePositions[index * 3 + 1] = y;
        this.spinePositions[index * 3 + 2] = z;
    }

    update(targetPosition, time) {
        if (!targetPosition) return;

        this.targetVelocity.subVectors(targetPosition, this.lastTargetPosition);
        
        const followDistance = 0.0; // How far behind the butterfly the snake's head should be
        const depthOffset = Z_LAYERS.foreground;

        let headTarget = new THREE.Vector3().copy(targetPosition);

        if (this.targetVelocity.lengthSq() > 0.0001) {
            const offsetDirection = this.targetVelocity.clone().normalize().negate();
            headTarget.addScaledVector(offsetDirection, followDistance);
        }

        // --- Wiggle Logic ---
        const wiggleFrequency = 20;
        const wiggleAmplitude = 20;

        const sideVector = new THREE.Vector3().crossVectors(this.targetVelocity, new THREE.Vector3(0, 0, 1));

        if (sideVector.lengthSq() > 0.0001) {
            sideVector.normalize();
            const wiggleOffset = Math.sin(time * wiggleFrequency) * wiggleAmplitude;
            headTarget.addScaledVector(sideVector, wiggleOffset);
        }

        this.lastTargetPosition.copy(targetPosition);

        // --- 1. CPU Logic: Inverse Kinematics ---
        this.spineTarget[0].lerp(headTarget, 0.1);

        // Drag Body
        const segmentLen = this.radius * 0.5;
        for (let i = 1; i < this.spineTarget.length; i++) {
            const current = this.spineTarget[i];
            const previous = this.spineTarget[i - 1];
            
            const dist = current.distanceTo(previous);
            if (dist > segmentLen) {
                const dir = new THREE.Vector3().subVectors(previous, current).normalize();
                const offset = dir.multiplyScalar(segmentLen);
                current.copy(previous).sub(offset);
            }
        }

        // --- 2. Update Data for GPU ---
        for (let i = 0; i < this.numSegments; i++) {
            this.updateSpineUniform(i, this.spineTarget[i].x, this.spineTarget[i].y, this.spineTarget[i].z);
        }

        this.mesh.material.uniforms.uTime.value = time;
    }

    disable() {
        if (this.mesh) {
            this.mesh.visible = false;
        }
    }
}