// postprocessing/PipelineManager.js
import { EffectComposer } from 'three/examples/jsm/postprocessing/EffectComposer.js';
import { RenderPass } from 'three/examples/jsm/postprocessing/RenderPass.js';
import { ShaderPass } from 'three/examples/jsm/postprocessing/ShaderPass.js';
import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';

import { getDeviceTier } from './performance.js';
import { debugLog } from "../debugger/debugLog.js";
import { debug } from 'three/tsl';
import * as THREE from 'three'

export class PipelineManager {
    constructor(renderer, scene, camera) {
        this.renderer = renderer;
        this.composer = new EffectComposer(renderer);
        this.camera = camera;

        // The base render pass is always required
        const renderPass = new RenderPass(scene, camera);
        this.composer.addPass(renderPass);

        this.tier = getDeviceTier();
        debugLog("Device Tier: " + this.tier, "ppm,dc");
        this.activePasses = new Map();

        this.fps = 60;

        this.localizedPass = null;
        this.localizedPassTarget = null;

        // 2. Configure Effect Behavior Ranges
        this.localConfig = {
            // Radius config (normalized screen units 0-1)
            minRadius: 0.05,       // Fully invisible when stopped
            maxRadius: 0.08,      // Size at top speed

            // Intensity (RGB shift offset)
            minOffset: 0.08,
            maxOffset: 0.15,      // Shift amount at top speed

            maxWarpStrength: 0.0,      // NEW - Max warp pinch amount

            // Dynamics
            speedThreshold: 4.0,  // Speed required to reach MAX effect
            smoothing: 0.1,        // Lerp factor (0.0 to 1.0). Lower is smoother/slower.
            softness: 0.02,
        };

        this.localTrackingVars = {
            // 3. State Variables
            tempVec: new THREE.Vector3(),
            prevPosition: new THREE.Vector3(),
            currentPosition: new THREE.Vector3(),
            currentSpeed: 0,
            smoothedSpeed: 0,
        }

        debugLog(`[Pipeline] Initialized at ${this.tier} tier.`, "ppm");
        window.addEventListener('resize', () => this.resize(window.innerWidth, window.innerHeight));
    }

    /**
     * Dynamically imports and adds an effect only if requested.
     */
    async addEffect(effectName, config = {}) {
        try {
            let pass;

            // Vite will code-split these dynamic imports
            switch (effectName) {
                case 'SMAA':
                    // We only want anti-aliasing on Medium/High tiers
                    // if (this.tier === 'LOW') return; 

                    const { SMAAPass } = await import('three/examples/jsm/postprocessing/SMAAPass.js');
                    pass = new SMAAPass(
                        window.innerWidth * this.renderer.getPixelRatio(),
                        window.innerHeight * this.renderer.getPixelRatio()
                    );
                    break;

                case 'Bloom':
                    // if (this.tier === 'LOW') return;

                    const { UnrealBloomPass } = await import('three/examples/jsm/postprocessing/UnrealBloomPass.js');
                    const { Vector2 } = await import('three');
                    pass = new UnrealBloomPass(new Vector2(window.innerWidth, window.innerHeight), 0.1, 0.1, 0.15);

                    // Apply config overrides
                    // if (config.strength) pass.strength = config.strength;
                    // if (config.radius) pass.radius = config.radius;
                    break;

                case 'Film':
                    // Grain is cheap, we can allow it on all tiers if desired, 
                    // or dial it back for low tiers.
                    const { FilmPass } = await import('three/examples/jsm/postprocessing/FilmPass.js');
                    pass = new FilmPass(config.noiseIntensity || 0.35, config.scanlines || 0.0, config.lines || 0, config.grayscale || false);
                    break;
                case 'Chromatic':
                    // if (this.tier === 'LOW') return; // Skip on low-end devices

                    // Dynamically import our custom shader
                    const { ChromaticAberrationShader } = await import('./shaders/ChromaticAberrationShader.js');

                    pass = new ShaderPass(ChromaticAberrationShader);
                    break;

                case "LocalChromatic":
                    debugLog("LocalChromatic 0 " + this.tier, "ppm,dc");

                    // if (this.tier === 'LOW') return; // Skip on low-end devices
                    if (config.target == null) returnl // no target provided 

                    this.localizedPassTarget = config.target;

                    // Dynamically import our custom shader
                    const { LocalizedChromaticShader } = await import('./shaders/LocalizedChromaticShader.js');
                    pass = new ShaderPass(LocalizedChromaticShader);
                    pass.uniforms.uResolution.value.set(window.innerWidth, window.innerHeight);
                    // pass.uniforms.uSoftness.value = this.localConfig.softness;
                    this.localizedPass = pass;
                    debugLog("LocalChromatic 1 pass added", "ppm,dc");
                    break;

                case 'OutputPass':
                    pass = new OutputPass();
                    break;
                // Add custom shaders like RGB Shift here...

                default:
                    debugLog(`[Pipeline] Effect ${effectName} not recognized.`, "ppm,warn");
                    return;
            }

            this.composer.addPass(pass);
            this.activePasses.set(effectName, pass);
            debugLog(`[Pipeline] ${effectName} loaded and added.`, "ppm");

            return pass; // Return the pass in case we want to animate its uniforms later

        } catch (error) {
            debugLog(`[Pipeline] Failed to load effect ${effectName}: ` + error, "ppm,error");
        }
    }

    // Call this inside your requestAnimationFrame loop
    render() {

        if (this.localizedPassTarget && this.localizedPass) {
            // // A. Get 3D World Position
            // this.localizedPassTarget.getWorldPosition(this.tempVec);

            // // B. Project to Camera Space (returns x/y in range -1 to 1)
            // this.tempVec.project(this.camera);

            // // C. Convert NDC (-1 to 1) to UV space (0 to 1) for the shader
            // const uvX = (this.tempVec.x + 1) / 2;
            // const uvY = (this.tempVec.y + 1) / 2;

            // // D. Update Shader Uniform
            // this.localizedPass.uniforms.uCenter.value.set(uvX, uvY);

            // // Optional: Animate radius based on model speed or depth!

            this.processLocalPassFrame();
        }

        this.composer.render();
    }

    processLocalPassFrame() {
        // --- 1. SPATIAL TRACKING (Same as previous step) ---
        this.localizedPassTarget.getWorldPosition(this.localTrackingVars.tempVec);
        this.localTrackingVars.tempVec.project(this.camera);
        this.localizedPass.uniforms.uCenter.value.set(
            (this.localTrackingVars.tempVec.x + 1) / 2,
            (this.localTrackingVars.tempVec.y + 1) / 2
        );

        // --- 2. VELOCITY CALCULATION ---
        this.localizedPassTarget.getWorldPosition(this.localTrackingVars.currentPosition);

        // Calculate raw distance moved since last frame
        // (Technically distance/delta, but frame-to-frame distance is fine for visuals)
        const distance = this.localTrackingVars.currentPosition.distanceTo(this.localTrackingVars.prevPosition);

        // Update previous position for next frame
        this.localTrackingVars.prevPosition.copy(this.localTrackingVars.currentPosition);

        // --- 3. SMOOTHING (LERP) ---
        // Smoothly interpolate currentSpeed towards the instantaneous 'distance'
        // This prevents the effect from flickering if movement is slightly uneven.
        this.localTrackingVars.smoothedSpeed += (distance - this.localTrackingVars.smoothedSpeed) * this.localConfig.smoothing;

        // Prevent negative speeds or tiny floating point noise when 'stopped'
        this.localTrackingVars.currentSpeed = Math.max(0, this.localTrackingVars.smoothedSpeed);

        // --- 4. MAP SPEED TO UNIFORMS ---

        // Calculate a 0.0 to 1.0 factor of how "fast" we are going relative to threshold
        const speedFactor = Math.min(this.localTrackingVars.currentSpeed / this.localConfig.speedThreshold, 1.0);

        // Map speedFactor to Radius (minRadius to maxRadius)
        const targetRadius = this.localConfig.minRadius + (this.localConfig.maxRadius - this.localConfig.minRadius) * speedFactor;


        // Map speedFactor to Offset (0.0 to maxOffset)
        // const targetOffset = this.localConfig.maxOffset * speedFactor;
        const targetOffset = this.localConfig.minOffset + (this.localConfig.maxOffset - this.localConfig.minOffset) * speedFactor;

        // if(targetRadius < 0.05 || targetOffset < 0.05)
        // {
        //     debugLog("speed factor " + speedFactor + " tr " + targetRadius + " to " + targetOffset, "ppm")
        // }

        // --- 5. UPDATE SHADER ---
        this.localizedPass.uniforms.uRadius.value = targetRadius;
        this.localizedPass.uniforms.uOffset.value = targetOffset;
        // this.localizedPass.uniforms.uWarpStrength.value = this.localConfig.maxWarpStrength * speedFactor;
    }

    // Call this when the window resizes
    resize(width, height) {
        debugLog("resize called ", "ppm")
        if (this.localizedPass)
            this.localizedPass.uniforms.uResolution.value.set(window.innerWidth, window.innerHeight);

        this.composer.setSize(width, height);
    }

    removeEffect(name) {
        const pass = this.activePasses.get(name)
        if (!pass) return

        this.composer.removePass(pass)
        this.passes.delete(name)
    }

    monitorFPS(delta) {
        fps = 1 / delta

        if (fps < 30) {
            ppm.removeEffect('bloom')
        }
    }
}