import * as THREE from 'three';
import { Text, getSelectionRects } from 'troika-three-text'

import gsap from "gsap"
import { debugLog } from "../../../debugger/debugLog.js";
import { COLORS } from '../../../siteData.js';

export default async function section5Forward(animManager) {

    debugLog("Section 5", "sec5_debug");

    const sectionDuration = 5;
    const butterflyPath = "paths/butterflySec5.json";

    animManager.section5ForwardTl = gsap.timeline({ paused: animManager.typeSectional })

    const phasingData = { progress: 0 };

    // moon 
    animManager.section5ForwardTl
        .to(phasingData, {
            progress: sectionDuration, // Animate from 0 to 1
            duration: sectionDuration,
            onStart: () => {
                debugLog("moon phase start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
            },
            onUpdate: () => {
                animManager.moonMaterial.uniforms.uTime.value = animManager.moonPhasingData.progress + phasingData.progress; // One full rotation for the phase cycle            
            },
            onComplete: () => {
                animManager.moonPhasingData.progress = animManager.moonPhasingData.progress + phasingData.progress;
                animManager.autoMoon = !animManager.autoMoon;
            }
        }, 0);

    animManager.section5ForwardTl
        // 1. The main fall. An "ease-in" makes it feel like it's accelerating due to gravity.
        .to(animManager.backgroundMesh.rotation, {
            x: -Math.PI / 2,
            duration: 3,
            ease: "power2.in",
            onStart: () => {
                debugLog("fall start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
            },
        }, 0)
        // --- CAMERA SHAKE ON IMPACT ---
        // We add a quick rotational shake and a positional jolt on the Z-axis.
        // This happens at the same time as the plane hits the "ground" (position parameter "<").

        // 2. The "impact" bounce. A small, quick rotation back up after the impact.
        .to(animManager.backgroundMesh.rotation, {
            x: -Math.PI / 2 + 0.1, // Bounce back up by a small amount
            duration: 0.4,
            ease: "power1.out",
            onStart: () => {
                debugLog("bounce1 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
            },
        }, 3)
        .to(animManager.activeCam.rotation, {
            z: '+=0.01', // small relative shake on Z
            x: '-=0.01', // small relative shake on X
            duration: 0.05,
            repeat: 5,
            yoyo: true,
            ease: "power1.inOut",
            onStart: () => {
                debugLog("bounce2 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
            },
        }, "<")
        .to(animManager.activeCam.position, {
            z: '-=15', // Jolt camera forward
            duration: 0.05,
            repeat: 1,
            yoyo: true,
            ease: "power1.inOut",
            onStart: () => {
                debugLog("bounce3 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
            },
        }, "<")
        // 3. The final settle. A slow ease into its final resting position.
        .to(animManager.backgroundMesh.rotation, {
            x: -Math.PI / 2,
            duration: 0.8,
            ease: "power1.in",
            onStart: () => {
                debugLog("bounce4 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
            },
        }, ">");

    animManager.section5ForwardTl.to(animManager.grassMesh.grassMaterial.uniforms.uColorIntensities.value, {
        [0]: 1.0,
        duration: 1,
        ease: "power2.out",
        onStart: () => {
            debugLog("grass1 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
        },
    }, 5);
    animManager.section5ForwardTl.to(animManager.grassMesh.grassMaterial.uniforms.uColorIntensities.value, {
        [1]: 1.0,
        duration: 1,
        ease: "power2.out",
        onStart: () => {
            debugLog("grass2 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
        },
    }, "<");

    animManager.section5ForwardTl.to(animManager.grassMesh.grassMaterial.uniforms.uColorRadii.value, {
        [0]: 200.0, // Your target full size
        duration: 1,
        ease: "back.out(1.2)",
        onStart: () => {
            debugLog("grass3 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
        },
    }, "<");

    animManager.section5ForwardTl.to(animManager.grassMesh.grassMaterial.uniforms.uColorRadii.value, {
        [1]: 200.0, // Your target full size
        duration: 1,
        ease: "back.out(1.2)",
        onStart: () => {
            debugLog("grass4 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
        },
    }, "<");


    const butterflyCurveId = await animManager.curveEditor.loadCurveFromPath(butterflyPath, "bfly-sec5-fwd");
    const butterflyCurve1 = animManager.curveEditor.curves[butterflyCurveId].curve3;

    const butterflyFlightData = { progress: 0 };
    animManager.section5ForwardTl.to(butterflyFlightData, {
        progress: 1,
        duration: 3,
        ease: "sine.inOut",
        // yoyo: true, // Go back and forth (optional)

        onReverseComplete: () => {
            animManager.cat.enabled(true);
            animManager.cat.enableFollowBehavior(null, false);
        },

        onStart: () => {
            debugLog("bfly start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
            animManager.cat.enabled(true);
            animManager.cat.enableFollowBehavior(animManager.butterfly, true);
        },

        onUpdate: () => {
            // 1. Get the position on the curve
            let position = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress, 0, 0);
            animManager.butterfly.position.copy(position);

            // 2. Handle Orientation (Make it face forward)
            // Look at a point slightly ahead in the future
            if (butterflyFlightData.progress + 0.01 < 1) {
                let lookAtPosition = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress + 0.01, 0, 0);
                animManager.butterfly.lookAt(lookAtPosition);
            }
            // const snakePos = position.add(animManager.bgMeshOffest);
            // animManager.snake.update(snakePos, butterflyFlightData.progress);
        }
    }, 6);

    // Add animations to the timeline
    animManager.section5ForwardTl.to(animManager.inMemoryText, {
        fillOpacity: 1,      // Fade in
        duration: 2.5,
        ease: "power2.out",
        onStart: () => {
            debugLog("memory1 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
        },
    }, 9)                  // The '0' tells it to start at the absolute beginning of the timeline
    animManager.section5ForwardTl.to(animManager.inMemoryText.position, {
        y: animManager.inMemoryText.position.y + (20 * animManager.scaleFactorVec.y),                // Float up to y: 0
        duration: 2.5,
        ease: "back.out(1.5)", // A slight overshoot for a cool floating effect

        onStart: () => {
            debugLog("memory2 start time " + animManager.section5ForwardTl.time(), "sec5_fwd");
        },
    }, "<");                 // Start at the same time as the opacity fade

    const targetTextColor = new THREE.Color(COLORS.content);

    animManager.section5ForwardTl.to(animManager.siteNavAboutTxt.material.color, {
        r: targetTextColor.r,
        g: targetTextColor.g,
        b: targetTextColor.b,
        duration: 0.8,
        ease: "bounce.out(1.5)"
    }, 11)
        .to(animManager.siteNavWorkTxt.material.color, {
            r: targetTextColor.r,
            g: targetTextColor.g,
            b: targetTextColor.b,
            duration: 0.8,
            ease: "bounce.out(1.5)"
        }, "<")
        .to(animManager.siteNavTestimonialsTxt.material.color, {
            r: targetTextColor.r,
            g: targetTextColor.g,
            b: targetTextColor.b,
            duration: 0.8,
            ease: "bounce.out(1.5)"
        }, "<")
        .to(animManager.siteNavAfterlifeTxt.material.color, {
            r: targetTextColor.r,
            g: targetTextColor.g,
            b: targetTextColor.b,
            duration: 0.8,
            ease: "bounce.out(1.5)"
        }, "<")
        .to(animManager.siteNavContactTxt.material.color, {
            r: targetTextColor.r,
            g: targetTextColor.g,
            b: targetTextColor.b,
            duration: 0.8,
            ease: "bounce.out(1.5)"
        }, "<")
        .to(animManager.siteNavUnderLine.material.color, {
            r: targetTextColor.r,
            g: targetTextColor.g,
            b: targetTextColor.b,
            duration: 0.8,
            ease: "bounce.out(1.5)"
        }, "<")


    // return "test";
    debugLog("Section 5 end", "sec5_debug");
    // return tl;
}