import * as THREE from 'three';
import { ImprovedNoise } from 'three/examples/jsm/math/ImprovedNoise.js'; // Assuming standard Vite + Three.js setup

// --- GENERATE 3D NOISE TEXTURE ONCE ---
const size = 128;
const data = new Uint8Array(size * size * size);
let i = 0;
const scale = 0.05;
const perlin = new ImprovedNoise();
const vector = new THREE.Vector3();

for (let z = 0; z < size; z++) {
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const d = 1.0 - vector.set(x, y, z).subScalar(size / 2).divideScalar(size).length();
      data[i] = (128 + 128 * perlin.noise((x * scale) / 1.5, y * scale, (z * scale) / 1.5)) * d * d;
      i++;
    }
  }
}

const cloudTexture = new THREE.Data3DTexture(data, size, size, size);
cloudTexture.format = THREE.RedFormat;
cloudTexture.minFilter = THREE.LinearFilter;
cloudTexture.magFilter = THREE.LinearFilter;
cloudTexture.unpackAlignment = 1;
cloudTexture.needsUpdate = true;

// --- SHADERS ---
const vertexShader = /* glsl */ `
  in vec3 position;
  uniform mat4 modelMatrix;
  uniform mat4 modelViewMatrix;
  uniform mat4 projectionMatrix;
  uniform vec3 cameraPos;
  
  out vec3 vOrigin;
  out vec3 vDirection;
  
  void main() {
    vec4 mvPosition = modelViewMatrix * vec4( position, 1.0 );
    vOrigin = vec3( inverse( modelMatrix ) * vec4( cameraPos, 1.0 ) ).xyz;
    vDirection = position - vOrigin;
    gl_Position = projectionMatrix * mvPosition;
  }
`;

const fragmentShader = /* glsl */ `
  precision highp float;
  precision highp sampler3D;
  
  uniform mat4 modelViewMatrix;
  uniform mat4 projectionMatrix;
  
  in vec3 vOrigin;
  in vec3 vDirection;
  
  out vec4 color;
  
  uniform vec3 base;
  uniform sampler3D map;
  uniform float threshold;
  uniform float range;
  uniform float opacity;
  uniform float steps;
  uniform float frame;
  
  uint wang_hash(uint seed) {
    seed = (seed ^ 61u) ^ (seed >> 16u);
    seed *= 9u;
    seed = seed ^ (seed >> 4u);
    seed *= 0x27d4eb2du;
    seed = seed ^ (seed >> 15u);
    return seed;
  }
  
  float randomFloat(inout uint seed) {
    return float(wang_hash(seed)) / 4294967296.;
  }
  
  vec2 hitBox( vec3 orig, vec3 dir ) {
    const vec3 box_min = vec3( - 0.5 );
    const vec3 box_max = vec3( 0.5 );
    vec3 inv_dir = 1.0 / dir;
    vec3 tmin_tmp = ( box_min - orig ) * inv_dir;
    vec3 tmax_tmp = ( box_max - orig ) * inv_dir;
    vec3 tmin = min( tmin_tmp, tmax_tmp );
    vec3 tmax = max( tmin_tmp, tmax_tmp );
    float t0 = max( tmin.x, max( tmin.y, tmin.z ) );
    float t1 = min( tmax.x, min( tmax.y, tmax.z ) );
    return vec2( t0, t1 );
  }
  
  float sample1( vec3 p ) {
    return texture( map, p ).r;
  }
  
  float shading( vec3 coord ) {
    float step = 0.01;
    return sample1( coord + vec3( - step ) ) - sample1( coord + vec3( step ) );
  }
  
  vec4 linearToSRGB( in vec4 value ) {
    return vec4( mix( pow( value.rgb, vec3( 0.41666 ) ) * 1.055 - vec3( 0.055 ), value.rgb * 12.92, vec3( lessThanEqual( value.rgb, vec3( 0.0031308 ) ) ) ), value.a );
  }
  
  void main(){
    vec3 rayDir = normalize( vDirection );
    vec2 bounds = hitBox( vOrigin, rayDir );
    if ( bounds.x > bounds.y ) discard;
    bounds.x = max( bounds.x, 0.0 );
    float stepSize = ( bounds.y - bounds.x ) / steps;
    uint seed = uint( gl_FragCoord.x ) * uint( 1973 ) + uint( gl_FragCoord.y ) * uint( 9277 ) + uint( frame ) * uint( 26699 );
    vec3 size = vec3( textureSize( map, 0 ) );
    float randNum = randomFloat( seed ) * 2.0 - 1.0;
    vec3 p = vOrigin + bounds.x * rayDir;
    p += rayDir * randNum * ( 1.0 / size );
    vec4 ac = vec4( base, 0.0 );
    for ( float i = 0.0; i < steps; i += 1.0 ) {
      float d = sample1( p + 0.5 );
      d = smoothstep( threshold - range, threshold + range, d ) * opacity;
      float col = shading( p + 0.5 ) * 3.0 + ( ( p.x + p.y ) * 0.25 ) + 0.2;
      ac.rgb += ( 1.0 - ac.a ) * d * col;
      ac.a += ( 1.0 - ac.a ) * d;
      if ( ac.a >= 0.95 ) break;
      p += rayDir * stepSize;
    }
    color = linearToSRGB( ac );
    if ( color.a == 0.0 ) discard;
  }
`;

function createVolumeCloud(width, height, depth, color, name = "") {
  // Use a 1x1x1 bounding box. The shader raymarching mathematics 
  // rely on a unit cube. We'll use scaling to achieve your desired width/height/depth.
  const boxGeometry = new THREE.BoxGeometry(1, 1, 1);

  const cloudMaterial = new THREE.RawShaderMaterial({
    glslVersion: THREE.GLSL3,
    uniforms: {
      base: { value: new THREE.Color(color) },
      map: { value: cloudTexture },          // Using the globally generated texture
      cameraPos: { value: new THREE.Vector3() },
      threshold: { value: 0 },
      opacity: { value: 0.25 },
      range: { value: 0.1 },
      steps: { value: 100 },
      frame: { value: 0 }
    },
    vertexShader,
    fragmentShader,
    side: THREE.BackSide, // Important for raymarching correctly inside the bounding volume
    transparent: true
  });
  const parameters = {
    threshold: 0.25,
    opacity: 0.25,
    range: 0.1,
    steps: 100
  };




  const cloudBox = new THREE.Mesh(boxGeometry, cloudMaterial);
  cloudBox.name = name;

  // Scale the mesh to your specified dimensions
  cloudBox.scale.set(width, height, depth);

  return {
    cloud: cloudBox,
    width: width,
    height: height,
    depth: depth
  };
};

export { createVolumeCloud };


export class RaymarchedCloudTexture {
  constructor(width, height, depth, color, name = "") {
    this.width = width;
    this.height = height;
    this.depth = depth;

    this.cloudScene = new THREE.Scene();

    // Create the Render Target
    this.renderTarget = new THREE.WebGLRenderTarget(width, height, {
      format: THREE.RGBAFormat,
      type: THREE.HalfFloatType
    });

    // Orthographic camera perfectly framing the width and height
    this.camera = new THREE.OrthographicCamera(-width / 2, width / 2, height / 2, -height / 2, 0.1, 300);
    this.camera.position.set(0, 0, -200);
    this.camera.lookAt(0, 0, 0);

    // Create actual 3D volume cloud
    const cloudData = createVolumeCloud(width, height, depth, color, name + "_internal");
    this.innerCloud = cloudData.cloud;
    this.innerCloud.material.uniforms.cameraPos.value.copy(this.camera.position);
    this.cloudScene.add(this.innerCloud);

    // The mesh to be added to the main scene
    const planeGeo = new THREE.PlaneGeometry(width, height);
    const planeMat = new THREE.MeshBasicMaterial({
      map: this.renderTarget.texture,
      transparent: true,
      depthWrite: false
    });

    // Proxy the material uniforms to allow GSAP animations on this mesh directly
    planeMat.uniforms = this.innerCloud.material.uniforms;

    this.mesh = new THREE.Mesh(planeGeo, planeMat);
    this.mesh.name = name;

    this.isComputing = true;
    this.needsUpdate = true;
    this.lastThreshold = -1;
  }

  get cloud() {
    return this.mesh;
  }

  // Use this to create additional clouds that share the exact same texture
  // and compute cost as the original cloud.
  createInstance(name = "") {
    const instMesh = new THREE.Mesh(this.mesh.geometry, this.mesh.material);
    instMesh.name = name;
    return instMesh;
  }

  update(renderer) {
    // Determine if we need to compute based on threshold uniform
    const currentThreshold = this.innerCloud.material.uniforms.threshold.value;
    if (currentThreshold !== this.lastThreshold) {
      this.isComputing = true;
      this.lastThreshold = currentThreshold;
    } else {
      this.isComputing = false;
    }

    // this.isComputing = true;
    // this.needsUpdate = true;

    if (this.isComputing || this.needsUpdate) {
      const oldRenderTarget = renderer.getRenderTarget();
      const oldClearColor = renderer.getClearColor(new THREE.Color());
      const oldClearAlpha = renderer.getClearAlpha();

      renderer.setClearColor(0x000000, 0);
      renderer.setRenderTarget(this.renderTarget);
      renderer.clear();
      renderer.render(this.cloudScene, this.camera);

      renderer.setClearColor(oldClearColor, oldClearAlpha);
      renderer.setRenderTarget(oldRenderTarget);
      this.needsUpdate = false;
    }
  }
}
