import * as THREE from 'three';
import { Text, getSelectionRects } from 'troika-three-text'

import gsap from "gsap"
import { debugLog } from "../../../debugger/debugLog.js";
import { COLORS } from '../../../siteData.js';

export default async function section4Forward(animManager) {

    debugLog("Section 3", "sec4_debug");


    const sectionDuration = 5;
    const butterflyPath = "paths/butterflySec4.json";
    const snakePath = "paths/snakeSec4.json";

    animManager.section4ForwardTl = gsap.timeline({ paused: animManager.typeSectional })

    const phasingData = { progress: 0 };

    // moon 
    animManager.section4ForwardTl
        .to(phasingData, {
            progress: sectionDuration, // Animate from 0 to 1
            duration: sectionDuration,
            onUpdate: () => {
                animManager.moonMaterial.uniforms.uTime.value = animManager.moonPhasingData.progress + phasingData.progress; // One full rotation for the phase cycle            
            },
            onComplete: () => {
                debugLog("moon completed section 3 ", "sec3_debug");
                animManager.moonPhasingData.progress = animManager.moonPhasingData.progress + phasingData.progress;
            }
        }, 0);
    const butterflyCurveId = await animManager.curveEditor.loadCurveFromPath(butterflyPath, "bfly-sec4-fwd");
    const butterflyCurve1 = animManager.curveEditor.curves[butterflyCurveId].curve3;

    const butterflyFlightData = { progress: 0 };
    animManager.section4ForwardTl.to(butterflyFlightData, {
        progress: 1,
        duration: sectionDuration - 2,
        ease: "sine.in",
        onUpdate: () => {
            let position = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress, 0, 0);
            animManager.butterfly.position.copy(position);
            if (butterflyFlightData.progress + 0.01 < 1) {
                let lookAtPosition = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress + 0.01, 0, 0);
                animManager.butterfly.lookAt(lookAtPosition);
            }
            const snakePos = position.add(animManager.bgMeshOffest);
            animManager.snake.update(snakePos, butterflyFlightData.progress);
        }
    }, 0);

    debugLog("Section 4 animManager.workRightNav.iconMesh is null " + (animManager.workRightNav.iconMesh == null), "sec4_debug");

    animManager.section4ForwardTl.to(animManager.workTextUniforms.uDissolve, { value: 1.2, duration: sectionDuration, ease: "none" }, 0);
    animManager.section4ForwardTl.to(animManager.workTitleUniforms.uDissolve, { value: 1.2, duration: sectionDuration, ease: "none" }, 0);
    animManager.section4ForwardTl.to(animManager.workBase.material, { opacity: 0.0, duration: sectionDuration, ease: "none" }, 0);
    animManager.section4ForwardTl.to(animManager.workRightNav.iconMesh.material, {
        opacity: 0.0, duration: sectionDuration, ease: "none",
        onComplete: () => {
            debugLog("Hiding work nav", "about_nav_bug2");

            animManager.workRightNav.iconMesh.layers.set(1);
            animManager.workLeftNav.iconMesh.layers.set(1);
            animManager.workLeftNav.layers.set(1);
            animManager.workRightNav.layers.set(1);

        }
    }, 0);
    animManager.section4ForwardTl.to(animManager.workLeftNav.iconMesh.material, { opacity: 0.0, duration: sectionDuration, ease: "none" }, 0);
    animManager.section4ForwardTl.to(animManager.projectBase.material, { opacity: 0.0, duration: sectionDuration, ease: "none" }, 0);
    animManager.section4ForwardTl.to(animManager.projectTitleUnderline.material, {
        linewidth: 0, duration: sectionDuration, ease: "expo.inOut",
        onUpdate: () => {
            animManager.aboutUnderline.material.needsUpdate = true;
        },
    }, 0);
    animManager.section4ForwardTl.to(animManager.projectIcon.material, {
        opacity: 0.0, duration: sectionDuration, ease: "none",
        onUpdate: () => {
            animManager.projectIcon.material.needsUpdate = true;
        },
    }, 0);


    animManager.projectTechStackMeshes.forEach((mesh, tech) => {
        animManager.section4ForwardTl.to(mesh.material, { opacity: 0.0, duration: sectionDuration, ease: "none" }, 0);

    });

    animManager.testimonialSec4StartPosY = animManager.testimonialGroup.position.y;

    animManager.section4ForwardTl.to(animManager.testimonialGroup.position, { y: animManager.testimonialGroup.position.y + (1450 * animManager.scaleFactor), duration: sectionDuration, ease: 'power2.inOut' }, 0);

    animManager.section4ForwardTl.to(animManager.grassMesh.grassUniforms.opacity, {
        value: 1.2, duration: 1, ease: "none",
        onStart: () => {
            animManager.growGrass();
            animManager.grassMesh.mesh.visible = true;
            animManager.animateGrass = true;
        }
    }, 0);

    animManager.section4ForwardTl.to(animManager.backdrop.material.uniforms.uOpacity, {
        value: 1.1,         // Target fully visible
        duration: 1,        // Over 3 seconds
        ease: "power2.inOut",
        onStart: () => {
            animManager.backdrop.visible = true;
            animManager.animateBackdrop = true;
        }
    }, 0);

    animManager.section4ForwardTl.to(animManager.litBG.material, {
        opacity: 1.0,
        duration: 1,        // Over 3 seconds
        ease: "power2.inOut"
    }, 0);

    debugLog("Section 4 end", "sec4_debug");
}