// #region --- MOON FUNCTIONS ---

function getMoonMaterial() {
  // 1. Load the Moon Texture
  // const textureLoader = new THREE.TextureLoader();
  // Replace with your high-def moon texture path
  const moonTexture = loadingController.getTextureLoader().load(siteContent.header_moon.texturePath);

  // 3. Create the Shader Material
  const moonMaterial = new THREE.ShaderMaterial({
    vertexShader: moonVertShader,
    fragmentShader: moonFragShader,
    uniforms: {
      uTexture: { value: moonTexture },
      uTime: { value: 0 },
      uTextureReveal: { value: 0 }, // Start at Stroke
      uPhaseStrength: { value: 0 }  // Start with No Shadow
    },
    transparent: true, // Needed for the ring transparency
  });

  return moonMaterial;
}


