function setTechStackLayout(content_width, scale_factor) {
  debugLog("setTechStackLayout " + content_width, "tech_stack");
  projectTechStackGroup.position.set(content_width / 2 - Math.round(cssData.tech_stack.width * scale_factor), -(cssData.tech_stack.height / 4) * scale_factor, 0);
  let rowIndex = 0;
  let rowWidth = 0;
  let columnIndex = 0;
  currentTechStackMeshes.forEach((mesh, tech) => {
    const meshWidth = siteContent.tech_stack.get(tech).width * scale_factor;
    debugLog("mesh width of " + tech + ": " + meshWidth, "work_section");
    if (rowWidth + meshWidth > cssData.tech_stack.width * scale_factor) {
      rowIndex++;
      rowWidth = 0;
      columnIndex = 0;
    }
    rowWidth += (cssData.tech_stack.gap * scale_factor);
    mesh.position.set(rowWidth, -rowIndex * (cssData.tech_stack.iconHeight * scale_factor), 0);
    mesh.scale.set(scale_factor, scale_factor, 1);
    rowWidth += meshWidth;

    columnIndex++;
  });
}

function positionReadMore(bodyMesh, readMoreMesh) {
  // Ensure the body text is finished rendering layout
  debugLog("positionReadMore called", "tech_stack");

  const renderInfo = bodyMesh.textRenderInfo;
  debugLog("positionReadMore called2 " + renderInfo.lastGlyphBounds, "tech_stack");
  if (renderInfo && renderInfo.lastGlyphBounds) {
    // lastGlyphBounds = [minX, minY, maxX, maxY]
    const [minX, minY, maxX, maxY] = renderInfo.lastGlyphBounds;

    // 1. Position the Read More mesh
    // We use maxX to place it to the right of the ellipsis
    // We use minY to align it to the text baseline
    const padding = 0.1; // Space between "..." and "Read More"

    readMoreMesh.position.set(
      maxX + padding,
      minY,
      0
    );

    // 2. Parent it (Optional but recommended)
    // This ensures if you move the bodyMesh, the 'Read More' follows
    bodyMesh.add(readMoreMesh);
    bodyMesh.sync();
  }

}

