function setAboutContent(index, force = false) {

  if (index == currentAboutIndex && !force)
    return;

  navTextObjects.forEach((item, itemIndex) => {
    // item.underline.visible = (index == itemIndex);
    gsap.to(item.underline.material, {
      linewidth: (index == itemIndex) ? THICK_LINE_WIDTH * 1.5 : 0, duration: 1.5, ease: "back.out",
      onUpdate: () => {
        item.underline.material.needsUpdate = true;
      },
      overwrite: "auto"
    });
  });
  if (index == 0) {
    ShowAboutAuthor(true);
    ShowAboutMe(false);
  }
  else if (index == 1) {
    ShowAboutAuthor(false);
    ShowAboutMe(true);
  }
  else if (index == 2) {
    // ShowAboutAuthor(false);
    // flickerComicPanelsOn();
    ShowAboutProcess();
  }
  currentAboutIndex = index;
}

function ShowAboutAuthor(show = true) {
  debugLog("ShowAboutAuthor " + show, "about_nav");
  if (!sectionalAnimManager.aboutTextUniforms)
    return;

  const disVal = show ? 0 : 1.2;
  const aboutAuthorTl = gsap.timeline();
  // debugLog("ShowAboutAuthor disVal " + disVal, "about_nav");

  gsap.to(
    sectionalAnimManager.aboutTextUniforms.uDissolve,
    {
      value: disVal,
      duration: 2.5,
      ease: "power.out",
      overwrite: "auto",
    });
}

function ShowAboutMe(show = true) {
  if (show) {
    if (!isComicActive()) {
      debugLog("showing comic ", "about_nav");
      animateComicPageIn(0, { force: true });
    }

  }
  else {
    if (isComicActive()) {
      debugLog("hiding comic ", "about_nav");
      animateOutComicPage();
    }

  }

}

function ShowAboutProcess(show = true) {
  gsap.to(sectionalAnimManager.aboutTitleUniforms.uTextColor.value, {
    r: 1.0, g: 0.0, b: 0.0, // example: animate to red
    duration: 2.5,
    ease: "power.out",
    overwrite: "auto",
  });
}

