function loadPageData(pageData, visible) {

  // return;
  debugLog("loadPage1Data", "comic");
  const comicSprites = [];
  activeHoveredPanel = null;

  pageData.forEach((panel) => {
    if (!panel.img_url) return; // Skip empty panels
    debugLog(panel.img_url + " : " + panel.size.w + " : " + panel.size.h, "comic");

    const [btnGroup, btnMat, btnSprite] = createComicPanelTextureButton(loadingController.getTextureLoader(), panel.img_url, panel.size.w, panel.size.h, "comic_panel", comicVert, comicFrag, 0xffffff);

    // Initial state is full grayscale
    btnMat.uniforms.uRadius.value = 0.0;

    //set pivot to bottom left
    btnSprite.geometry.translate(panel.size.w / 2, panel.size.h / 2, 0);
    btnSprite.position.set(-960 / 2 + panel.posX, -panel.size.h / 2, Z_LAYERS.foreground); // Set Z layer for comic
    btnSprite.userData.size = { width: panel.size.w, height: panel.size.h };
    btnSprite.visible = visible;
    btnSprite.layers.set(1);
    btnGroup.layers.set(1);
    // const axesHelper = new THREE.AxesHelper(200); 
    // btnGroup.add(axesHelper); // Add axes helper to the sprite for debugging

    aboutComicBase.add(btnGroup);
    comicSprites.push(btnSprite);
    // cursorController.registerClickableObject('main', btnGroup);
  });

  return comicSprites;
}

async function loadComicPages() {
  debugLog("loadComicPages", "comic");
  const comicPagesData = Array.isArray(siteContent.about_comic_strip)
    ? siteContent.about_comic_strip
    : Object.values(siteContent.about_comic_strip);
  // const comicPages = [];
  let index = 0
  for (const pageData of comicPagesData) {
    comicPages.push(loadPageData(pageData, false));
    index++;
    await new Promise((resolve) => setTimeout(resolve, 1000));
    debugLog("Loaded comic page with " + pageData.length + " panels", "comic");

  }
  return comicPages;
}

function handleComicPanelHover(panelObject, mousePos, intersect) {
  if (!panelObject) return;

  // If moved to a different comic panel, fade out previous
  if (activeHoveredPanel && activeHoveredPanel !== panelObject) {
    handleComicPanelLeave(activeHoveredPanel);
  }
  activeHoveredPanel = panelObject;

  const iconMesh = panelObject.iconMesh || (panelObject.material?.uniforms?.uMouse ? panelObject : panelObject.children?.find(c => c.material?.uniforms?.uMouse));
  if (!iconMesh || !iconMesh.material || !iconMesh.material.uniforms || !iconMesh.material.uniforms.uMouse) return;

  const uniforms = iconMesh.material.uniforms;

  if (intersect && intersect.uv) {
    uniforms.uMouse.value.copy(intersect.uv);
  } else if (cursorController && activeCamera) {
    const raycaster = cursorController.raycaster || new THREE.Raycaster();
    raycaster.setFromCamera(cursorController.mouse, activeCamera);
    const hits = raycaster.intersectObject(iconMesh, true);
    if (hits.length > 0 && hits[0].uv) {
      uniforms.uMouse.value.copy(hits[0].uv);
    }
  } else if (mousePos && typeof mousePos.x === 'number') {
    uniforms.uMouse.value.set(mousePos.x, mousePos.y);
  }

  // Smoothly expand reveal radius
  gsap.to(uniforms.uRadius, {
    value: 0.85,
    duration: 1.0,
    ease: "power2.out",
    overwrite: "auto"
  });
}

function handleComicPanelLeave(panelObject) {
  const target = panelObject || activeHoveredPanel;
  if (!target) {
    comicPanels.forEach((panel) => {
      const iconMesh = panel.iconMesh || (panel.material?.uniforms?.uRadius ? panel : panel.children?.find(c => c.material?.uniforms?.uRadius));
      if (iconMesh?.material?.uniforms?.uRadius) {
        gsap.to(iconMesh.material.uniforms.uRadius, {
          value: 0.0,
          duration: 0.35,
          ease: "power2.out",
          overwrite: "auto"
        });
      }
    });
    activeHoveredPanel = null;
    return;
  }

  const iconMesh = target.iconMesh || (target.material?.uniforms?.uRadius ? target : target.children?.find(c => c.material?.uniforms?.uRadius));
  if (iconMesh?.material?.uniforms?.uRadius) {
    gsap.to(iconMesh.material.uniforms.uRadius, {
      value: 0.0,
      duration: 0.35,
      ease: "power2.out",
      overwrite: "auto"
    });
  }

  if (!panelObject || panelObject === activeHoveredPanel) {
    activeHoveredPanel = null;
  }
}

