/**
 * Animates in the comic page sprites referenced in comicPages with a vertical scroll effect.
 *
 * Incoming sprites animate in from bottom to top.
 * Existing page sprites (if any) animate out from bottom to top.
 * Fully reversible:
 * - Supports reverse scrolling direction (top to bottom) via direction parameter,
 *   reverse boolean, or when navigating to an earlier page index.
 * - Returns a GSAP timeline configured so that calling `tl.reverse()` smoothly
 *   rewinds the transition back to the previous page state.
 *
 * @param {number|string} [targetPageIndex=0] - Index of the comic page to show, or 'next' / 'prev'.
 * @param {Object|number|boolean} [options={}] - Transition configuration, direction (1 or -1), or reverse flag (boolean).
 * @param {number} [options.direction] - 1 for forward (bottom to top), -1 for reverse (top to bottom).
 * @param {boolean} [options.reverse=false] - If true, reverses scroll direction (top to bottom).
 * @param {number} [options.duration=0.8] - Animation duration in seconds.
 * @param {string} [options.ease="power2.inOut"] - GSAP easing curve.
 * @param {number} [options.stagger=0.04] - Delay between consecutive panels on the same page.
 * @param {number} [options.scrollDistance=550] - Vertical offset distance for enter/exit travel.
 * @param {boolean} [options.force=false] - If true, animates even if targetPageIndex is already current.
 * @param {Function} [options.onStart] - Callback invoked when the animation begins.
 * @param {Function} [options.onComplete] - Callback invoked when the animation completes.
 * @returns {gsap.core.Timeline|null} The GSAP timeline animating the transition.
 */
function animateComicPageIn(targetPageIndex = 0, options = {}) {
  if (!comicPages || comicPages.length === 0) {
    debugLog("animateComicPage: comicPages is empty or not loaded yet.", "comic,tl_rev");
    return null;
  }

  // Parse options
  let direction = null;
  let duration = 0.8;
  let ease = "power2.inOut";
  let stagger = 0.04;
  let onComplete = null;
  let onStart = null;
  let force = false;

  if (typeof options === "boolean") {
    direction = options ? -1 : 1;
  } else if (typeof options === "number") {
    direction = options < 0 ? -1 : 1;
  } else if (typeof options === "object" && options !== null) {
    if (typeof options.reverse === "boolean") {
      direction = options.reverse ? -1 : 1;
    } else if (typeof options.direction === "number") {
      direction = options.direction < 0 ? -1 : 1;
    }
    if (typeof options.duration === "number") duration = options.duration;
    if (typeof options.ease === "string") ease = options.ease;
    if (typeof options.stagger === "number") stagger = options.stagger;
    if (typeof options.onComplete === "function") onComplete = options.onComplete;
    if (typeof options.onStart === "function") onStart = options.onStart;
    if (typeof options.force === "boolean") force = options.force;
  }

  // Handle semantic string targets
  if (targetPageIndex === "next") {
    targetPageIndex = (currentComicPageIndex + 1) % comicPages.length;
    if (direction === null) direction = 1;
  } else if (targetPageIndex === "prev") {
    targetPageIndex = currentComicPageIndex <= 0 ? comicPages.length - 1 : currentComicPageIndex - 1;
    if (direction === null) direction = -1;
  }

  // Ensure index is an integer within valid range (wrapping around)
  targetPageIndex = ((Math.floor(targetPageIndex) % comicPages.length) + comicPages.length) % comicPages.length;

  // Determine direction automatically if not explicitly provided
  if (direction === null) {
    if (currentComicPageIndex !== -1 && targetPageIndex < currentComicPageIndex) {
      direction = -1; // Moving backwards in page order
    } else {
      direction = 1;  // Moving forward or first page reveal
    }
  }

  // If target page is already active and force is not set, skip
  if (!force && currentComicPageIndex === targetPageIndex) {
    debugLog(`animateComicPage: Page ${targetPageIndex} is already active.`, "comic,tl_rev");
    return null;
  }

  const nextSprites = comicPages[targetPageIndex];
  if (!nextSprites || nextSprites.length === 0) {
    debugLog(`animateComicPage: No sprites found for page ${targetPageIndex}.`, "comic,tl_rev");
    return null;
  }

  const previousIndex = currentComicPageIndex;
  const prevSprites = previousIndex >= 0 && previousIndex < comicPages.length
    ? comicPages[previousIndex]
    : null;

  // If a transition is already in-flight, immediately complete it
  if (currentComicTimeline && currentComicTimeline.isActive()) {
    currentComicTimeline.progress(1);
  }

  // Prepare incoming sprites
  nextSprites.forEach((sprite) => {
    if (sprite.userData.baseY === undefined) {
      sprite.userData.baseY = sprite.position.y;
    }
    if (sprite.userData.baseScaleY === undefined) {
      sprite.userData.baseScaleY = sprite.scale.y;
    }
    const baseY = sprite.userData.baseY;
    const baseScaleY = sprite.userData.baseScaleY;

    // Initial state: scale y = 0, bottom aligned
    sprite.scale.y = 0;
    sprite.position.y = baseY - baseScaleY / 2;

    sprite.material.uniforms.uRadius.value = 0.0;
    sprite.visible = true;
    sprite.layers.set(0);
    if (sprite.parent && sprite.parent !== aboutComicBase) {
      sprite.parent.visible = true;
    }
  });

  // Prepare outgoing sprites (if any)
  if (prevSprites) {
    prevSprites.forEach((sprite) => {
      if (sprite.userData.baseY === undefined) {
        sprite.userData.baseY = sprite.position.y;
      }
      if (sprite.userData.baseScaleY === undefined) {
        sprite.userData.baseScaleY = sprite.scale.y;
      }
      sprite.scale.y = sprite.userData.baseScaleY;
      sprite.position.y = sprite.userData.baseY;

      sprite.visible = true;
      if (sprite.parent && sprite.parent !== aboutComicBase) {
        sprite.parent.visible = true;
      }
    });
  }

  const tl = gsap.timeline({
    onStart: () => {
      debugLog(`animateComicPage: Transitioning from page ${previousIndex} to ${targetPageIndex} (direction: ${direction})`, "comic");
      if (typeof onStart === "function") onStart();
    },
    onComplete: () => {
      // Hide outgoing page sprites after they have scaled out
      if (prevSprites) {
        prevSprites.forEach((sprite) => {
          sprite.visible = false;
          if (sprite.parent && sprite.parent !== aboutComicBase) {
            sprite.parent.visible = false;
            sprite.layers.set(1);
          }
          sprite.position.y = sprite.userData.baseY ?? 0;
          sprite.scale.y = sprite.userData.baseScaleY ?? 1;
        });
      }

      // Ensure incoming page sprites remain visible and at resting position
      nextSprites.forEach((sprite) => {
        sprite.visible = true;
        if (sprite.parent && sprite.parent !== aboutComicBase) {
          sprite.parent.visible = true;
        }
        sprite.position.y = sprite.userData.baseY ?? 0;
        sprite.scale.y = sprite.userData.baseScaleY ?? 1;
      });

      currentComicPageIndex = targetPageIndex;
      debugLog(`animateComicPage: Reached page ${targetPageIndex}`, "comic");
      if (typeof onComplete === "function") onComplete();
    },
    onReverseComplete: () => {
      // Reverse support for tl.reverse():
      // Hide incoming page sprites and return them to entrance position
      nextSprites.forEach((sprite) => {
        sprite.visible = false;
        if (sprite.parent && sprite.parent !== aboutComicBase) {
          sprite.parent.visible = false;
        }
        const baseScaleY = sprite.userData.baseScaleY ?? 1;
        sprite.scale.y = 0;
        sprite.position.y = (sprite.userData.baseY ?? 0) - baseScaleY / 2;
      });

      // Restore previous page sprites to resting position and make visible
      if (prevSprites) {
        prevSprites.forEach((sprite) => {
          sprite.visible = true;
          if (sprite.parent && sprite.parent !== aboutComicBase) {
            sprite.parent.visible = true;
          }
          sprite.position.y = sprite.userData.baseY ?? 0;
          sprite.scale.y = sprite.userData.baseScaleY ?? 1;
        });
      }

      currentComicPageIndex = previousIndex;
      debugLog(`animateComicPage: Reversed back to page ${previousIndex}`, "comic");
    }
  });

  // Animate outgoing sprites scaling to 0 from bottom to top (bottom moves up towards fixed top)
  if (prevSprites && prevSprites.length > 0) {
    prevSprites.forEach((sprite, index) => {
      const baseY = sprite.userData.baseY ?? 0;
      const baseScaleY = sprite.userData.baseScaleY ?? 1;

      tl.fromTo(
        sprite.scale,
        { y: baseScaleY },
        {
          y: 0,
          duration: duration,
          ease: ease,
          overwrite: "auto"
        },
        index * stagger
      );

      tl.fromTo(
        sprite.position,
        { y: baseY },
        {
          y: baseY + baseScaleY / 2,
          duration: duration,
          ease: ease,
          overwrite: "auto"
        },
        index * stagger
      );
    });
  }

  // Animate incoming sprites scaling from 0 to 1 on y axis, rising from bottom to top (top moves up from fixed bottom)
  nextSprites.forEach((sprite, index) => {
    const baseY = sprite.userData.baseY ?? 0;
    const baseScaleY = sprite.userData.baseScaleY ?? 1;

    tl.fromTo(
      sprite.scale,
      { y: 0 },
      {
        y: baseScaleY,
        duration: duration,
        ease: ease,
        overwrite: "auto"
      },
      index * stagger
    );

    tl.fromTo(
      sprite.position,
      { y: baseY - baseScaleY / 2 },
      {
        y: baseY,
        duration: duration,
        ease: ease,
        overwrite: "auto"
      },
      index * stagger
    );
  });

  currentComicTimeline = tl;
  currentComicPageIndex = targetPageIndex;

  return tl;
}

function nextComicPage(options) {

  return animateComicPageIn("next", options);
}

function prevComicPage(options) {
  return animateComicPageIn("prev", options);
}

function animateOutComicPage() {
  let direction = null;
  let duration = 0.8;
  let ease = "power2.inOut";
  let stagger = 0.04;
  let onComplete = null;
  let onStart = null;
  let force = false;

  const prevSprites = comicPages[currentComicPageIndex];

  if (prevSprites) {
    prevSprites.forEach((sprite) => {
      if (sprite.userData.baseY === undefined) {
        sprite.userData.baseY = sprite.position.y;
      }
      if (sprite.userData.baseScaleY === undefined) {
        sprite.userData.baseScaleY = sprite.scale.y;
      }
      sprite.scale.y = sprite.userData.baseScaleY;
      sprite.position.y = sprite.userData.baseY;

      sprite.visible = true;
      if (sprite.parent && sprite.parent !== aboutComicBase) {
        sprite.parent.visible = true;
      }
    });
  }

  const tl = gsap.timeline({
    onStart: () => {
      if (typeof onStart === "function") onStart();
    },
    onComplete: () => {
      // Hide outgoing page sprites after they have scaled out
      if (prevSprites) {
        prevSprites.forEach((sprite) => {
          sprite.visible = false;
          if (sprite.parent && sprite.parent !== aboutComicBase) {
            sprite.parent.visible = false;
            sprite.layers.set(1);
          }
          sprite.position.y = sprite.userData.baseY ?? 0;
          sprite.scale.y = sprite.userData.baseScaleY ?? 1;
        });
      }

      if (typeof onComplete === "function") onComplete();
    },
    onReverseComplete: () => {
      // Reverse support for tl.reverse():
      // Hide incoming page sprites and return them to entrance position


      // Restore previous page sprites to resting position and make visible
      if (prevSprites) {
        prevSprites.forEach((sprite) => {
          sprite.visible = true;
          if (sprite.parent && sprite.parent !== aboutComicBase) {
            sprite.parent.visible = true;
          }
          sprite.position.y = sprite.userData.baseY ?? 0;
          sprite.scale.y = sprite.userData.baseScaleY ?? 1;
        });
      }


    }
  });

  // Animate outgoing sprites scaling to 0 from bottom to top (bottom moves up towards fixed top)
  if (prevSprites && prevSprites.length > 0) {
    prevSprites.forEach((sprite, index) => {
      const baseY = sprite.userData.baseY ?? 0;
      const baseScaleY = sprite.userData.baseScaleY ?? 1;

      tl.fromTo(
        sprite.scale,
        { y: baseScaleY },
        {
          y: 0,
          duration: duration,
          ease: ease,
          overwrite: "auto"
        },
        index * stagger
      );

      tl.fromTo(
        sprite.position,
        { y: baseY },
        {
          y: baseY + baseScaleY / 2,
          duration: duration,
          ease: ease,
          overwrite: "auto"
        },
        index * stagger
      );
    });
  }
  currentComicPageIndex = -1;
}

function isComicActive() {
  if (comicPages.length == 0)
    return false;
  if (currentComicPageIndex == -1)
    return false;
  const comicSprites = comicPages[currentComicPageIndex];

  return comicSprites[0].visible;
}
