// 2. Request effects asynchronously. 
// The manager will automatically ignore heavy effects if on a LOW tier device.
async function setupPostProcessing() {

  // 1. Define a custom ID for this process
  const processId = 'postprocessing-shaders';

  // 2. Tell the loading manager that a custom task has started
  loadingController.manager.itemStart(processId);

  try {
    // Run your sequential pipeline setup as normal
    await pipeline.addEffect('SMAA');
    await pipeline.addEffect('LocalChromatic', { target: butterfly });
    await pipeline.addEffect('Film', { noiseIntensity: 0.15 });
    // await pipeline.addEffect('Bloom', { strength: 0.1, radius: 0.1 });

    await pipeline.addEffect('OutputPass');

    // 3. Tell the loading manager the task is completely finished
    loadingController.manager.itemEnd(processId);

  } catch (error) {
    console.error("Failed to load post-processing effects:", error);

    // 4. If an import fails, notify the manager so it doesn't hang infinitely
    loadingController.manager.itemError(processId);
  }
}

