function switchCamera() {
  if (activeCamera === orthoCamera) {
    activeCamera = perspectiveCamera;
    debugLog("Switched to Perspective Camera");
  } else {
    activeCamera = orthoCamera;
    debugLog("Switched to Orthographic Camera");
  }
  updateLayout(); // Re-run layout to ensure camera is correct
}

//#region Mouse and Cursor 

function findButtonParent(object) {
  // If the object itself has an ID in userData, it's our button
  if (!object)
    return null;
  if (!object.userData)
    return null;
  if (object.userData && object.userData.id) {
    return object;
  }
  // If not, check its parent (and so on)
  if (object.parent) {
    debugLog("parent found in hierarchy: " + object.parent.name, "mouse_event");
    return findButtonParent(object.parent);
  }
  return null;
}

function clickableObjectHoveredUpon(hoveredObject, mousePos, intersect) {
  const buttonGroup1 = findButtonParent(hoveredObject);
  if (buttonGroup1) {
    debugLog("Hovered Button Name:" + buttonGroup1.name, "about_nav_bug");
    if (buttonGroup1.userData)
      debugLog("Hovered Button ID:" + buttonGroup1.userData.id, "about_nav_bug");
  }
  return; // Disable hover effects for now
  if (!hoveredObject) {
    if (activeHoveredPanel) {
      handleComicPanelLeave();
    }
    return;
  }

  const buttonGroup = findButtonParent(hoveredObject);

  if (buttonGroup) {
    // debugLog("Hovered Button Name:" + buttonGroup.name, "comic");
    // debugLog("Hovered Button ID:" + buttonGroup.userData.id, "comic");

    // handleButtonClick(buttonGroup.userData.id);
    if (buttonGroup.userData.id === 'comic_panel') {
      // Handle comic panel hover
      handleComicPanelHover(buttonGroup, mousePos, intersect);
    } else if (activeHoveredPanel) {
      handleComicPanelLeave();
    }
  } else if (activeHoveredPanel) {
    handleComicPanelLeave();
  }
}

function clickableObjectClicked(clickedObject, mouse) {

  debugLog("Clicked Object null:" + (clickedObject == null), "cc,comic");

  if (clickedObject == null) {
    if (contactCardManager && contactCardManager.handleClick(mouse)) {
      debugLog("ContactCard handled the click event.", "cc");
      return; // Input consumed by ContactCard
    }
    return;
  }

  const buttonGroup = findButtonParent(clickedObject);

  if (buttonGroup) {
    debugLog("Clicked Button Name:" + buttonGroup.name, "comic");
    debugLog("Clicked Button ID:" + buttonGroup.userData.id, "comic");

    handleButtonClick(buttonGroup.userData.id);
  }
}

function handleButtonClick(id) {
  debugLog("handleButtonClick for id: " + id, "mouse_event, comic");
  switch (id) {
    case 'home-btn':
      // Trigger camera move to home position
      break;
    case 'settings-btn':
      // Open a settings menu
      break;
    case 'work_left':
      --currentProjectIndex;
      loadProjectDataByCurrentIndex();
      break;
    case 'work_right':
      ++currentProjectIndex;
      loadProjectDataByCurrentIndex();
      break;
    case 'testi_nav_l':
      --currentTestimonialIndex;
      loadTestimonialDataByCurrentIndex();
      break;
    case 'testi_nav_r':
      ++currentTestimonialIndex;
      loadTestimonialDataByCurrentIndex();
      break;
    case 'nav_about':
      sectionalAnimManager.goto(2);
      break;
    case 'nav_work':
      sectionalAnimManager.goto(3);
      break;
    case 'nav_testimonials':
      sectionalAnimManager.goto(4);
      break;
    case 'nav_afterlife':
      sectionalAnimManager.goto(5);
      break;
    case 'nav_contact':
      if (contactCardManager) contactCardManager.show();
      break;
    case 'about_nav_left':
      prevComicPage({ onComplete: flickerComicPanelsOn });
      break;
    case 'about_nav_right':
      nextComicPage({ onComplete: flickerComicPanelsOn });
      break;
    case 'about_nav_author':
      setAboutContent(0);
      break;
    case 'about_nav_me':
      if (sectionalAnimManager.index != 2)
        sectionalAnimManager.goto(2);
      else {
        setAboutContent(1);
        flickerComicPanelsOn();
      }
      break;
    case 'about_nav_process':
      setAboutContent(2);
      break;
    default:
      debugLog("No action defined for:", id);
  }
}
