export function createProfiler(renderer, maxSamples = 600) {
    const samples = [];

    let frameCount = 0;
    let lastFpsTime = performance.now();
    let fps = 0;

    // Timing variables
    let frameStartTime = performance.now();
    let frameCpuTime = 0;
    let frameInterval = 0; // Time between rAF calls

    function beginFrame() {
        const now = performance.now();
        frameInterval = now - frameStartTime;
        frameStartTime = now;
        frameCount++;

        if (now - lastFpsTime >= 1000) {
            fps = frameCount;
            frameCount = 0;
            lastFpsTime = now;
        }
    }

    // Call this AFTER renderer.render()
    function endFrame() {
        // Calculate true CPU execution time spent in this frame
        frameCpuTime = performance.now() - frameStartTime;
    }

    function sample() {
        const memory = performance.memory;

        const data = {
            timestamp: performance.now(),

            fps,
            frameTime: frameCpuTime,  // The actual execution time
            frameInterval, // ~16.6ms at 60fps

            jsHeapUsed: memory?.usedJSHeapSize ?? null,
            jsHeapTotal: memory?.totalJSHeapSize ?? null,

            drawCalls: renderer.info.render.calls,
            triangles: renderer.info.render.triangles,
            lines: renderer.info.render.lines,
            points: renderer.info.render.points,

            geometries: renderer.info.memory.geometries,
            textures: renderer.info.memory.textures,

            pixelRatio: renderer.getPixelRatio(),
            canvasWidth: renderer.domElement.width,
            canvasHeight: renderer.domElement.height,
        };

        samples.push(data);

        // Prevent infinite memory growth by keeping only the latest samples
        if (samples.length > maxSamples) {
            samples.shift(); // Remove the oldest sample
        }

        return data;
    }

    function getSamples() {
        return samples;
    }

    return {
        beginFrame,
        endFrame,
        sample,
        getSamples,
    };
}