import * as THREE from 'three';
import grassShader from './shaders/grass.js';
import { debug } from 'three/tsl';
import { debugLog } from '../debugger/debugLog.js';

const PLANE_SIZE = 2500;
const BLADE_COUNT = 150000;
const BLADE_WIDTH = 10.0;
const BLADE_HEIGHT = 60;
const BLADE_HEIGHT_VARIATION = 80;

// const PLANE_SIZE = 20;
// const BLADE_COUNT = 50000;
// const BLADE_WIDTH = 0.1;
// const BLADE_HEIGHT = 0.8;
// const BLADE_HEIGHT_VARIATION = 0.6;

const MAX_MODELS = 2;

export class GrassMesh {
  constructor(scene, plane_size, blade_count, blade_width, blade_height, blade_height_variation) {
    this.scene = scene;

    this.mesh = null;

    this.plane_size = plane_size || PLANE_SIZE;
    this.blade_count = blade_count || BLADE_COUNT;
    this.blade_width = blade_width || BLADE_WIDTH;
    this.blade_height = blade_height || BLADE_HEIGHT;
    this.blade_height_variation = blade_height_variation || BLADE_HEIGHT_VARIATION;

    // Grass Texture
    const grassTexture = new THREE.TextureLoader().load('textures/grass.jpg');
    const cloudTexture = new THREE.TextureLoader().load('textures/cloud.jpg');
    cloudTexture.wrapS = cloudTexture.wrapT = THREE.RepeatWrapping;

    // Time Uniform
    this.startTime = Date.now();
    const timeUniform = { type: 'f', value: 0.0 };

    // Grass Shader
    this.grassUniforms = THREE.UniformsUtils.merge([
      THREE.UniformsLib.fog, // 1. Inject the built-in Three.js fog uniforms
      {
        textures: { value: [grassTexture, cloudTexture] },
        iTime: timeUniform,
        opacity: { value: 0 },
        // uModelPos: { value: new THREE.Vector3(1000, 1000, 500) }, 
        // uColorRadius: { value: 50.0 }, // Adjust this value to change the color bubble size
        // uColorIntensity: { value: 0.0 },

        uModelPositions: { value: new Array(MAX_MODELS).fill().map(() => new THREE.Vector3(0, 0, 0)) },
        uColorRadii: { value: new Array(MAX_MODELS).fill(50.0) },
        uColorIntensities: { value: new Array(MAX_MODELS).fill(0.0) },
      }]);

    this.grassMaterial = new THREE.ShaderMaterial({
      uniforms: this.grassUniforms,
      vertexShader: grassShader.vert,
      fragmentShader: grassShader.frag,
      vertexColors: true,
      side: THREE.DoubleSide,
      transparent: true,
      // depthWrite: false
      fog: true, // Tell Three.js to send scene.fog data to this material
    });

  }

  animate() {
    const elapsedTime = Date.now() - this.startTime;
    this.grassMaterial.uniforms.iTime.value = elapsedTime;

  }

  // 2. Add this new method to update the position from your main render loop
  // updateModelPosition(x, y, z) {
  //   if (this.grassMaterial) {
  //     this.grassMaterial.uniforms.uModelPos.value.set(x, y, z);
  //   }
  // }

  updateModelPosition(index, x, y, z) {
    debugLog("updateModelPosition called with index " + index, "grass_debug");
    if (this.grassMaterial && index < MAX_MODELS) {
      this.grassMaterial.uniforms.uModelPositions.value[index].set(x, y, z);
    }
  }

  convertRange(val, oldMin, oldMax, newMin, newMax) {
    return (((val - oldMin) * (newMax - newMin)) / (oldMax - oldMin)) + newMin;
  }

  generateField() {
    const VERTEX_COUNT = 5;
    const INDEX_COUNT = 9;

    const totalVertices = this.blade_count * VERTEX_COUNT;
    const positions = new Float32Array(totalVertices * 3);
    const uvs = new Float32Array(totalVertices * 2);
    const colors = new Float32Array(totalVertices * 3);
    const indices = new Uint32Array(this.blade_count * INDEX_COUNT);

    let posIdx = 0;
    let uvIdx = 0;
    let colIdx = 0;
    let indIdx = 0;

    const surfaceMin = this.plane_size / 2 * -1;
    const surfaceMax = this.plane_size / 2;
    const radius = this.plane_size / 2;

    for (let i = 0; i < this.blade_count; i++) {
      const r = radius * Math.sqrt(Math.random());
      const theta = Math.random() * 2 * Math.PI;
      const x = r * Math.cos(theta);
      const y = r * Math.sin(theta);

      const uvX = this.convertRange(x, surfaceMin, surfaceMax, 0, 1);
      const uvY = this.convertRange(y, surfaceMin, surfaceMax, 0, 1);

      this.generateBlade(x, 0, y, i * VERTEX_COUNT, uvX, uvY, positions, posIdx, uvs, uvIdx, colors, colIdx, indices, indIdx);

      posIdx += VERTEX_COUNT * 3;
      uvIdx += VERTEX_COUNT * 2;
      colIdx += VERTEX_COUNT * 3;
      indIdx += INDEX_COUNT;
    }

    const geom = new THREE.BufferGeometry();
    geom.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    geom.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
    geom.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    geom.setIndex(new THREE.BufferAttribute(indices, 1));
    geom.computeVertexNormals();
    // geom.computeFaceNormals();

    this.mesh = new THREE.Mesh(geom, this.grassMaterial);
    this.scene.add(this.mesh);
  }

  generateBlade(centerX, centerY, centerZ, vArrOffset, uvX, uvY, positions, posIdx, uvs, uvIdx, colors, colIdx, indices, indIdx) {
    const MID_WIDTH = this.blade_width * 0.5;
    const TIP_OFFSET = 0.1;
    const height = this.blade_height + (Math.random() * this.blade_height_variation);

    const yaw = Math.random() * Math.PI * 2;
    const sinYaw = Math.sin(yaw);
    const cosYaw = Math.cos(yaw);

    const tipBend = Math.random() * Math.PI * 2;
    const sinTipBend = Math.sin(tipBend);
    const cosTipBend = Math.cos(tipBend);

    const halfWidth = this.blade_width * 0.5;
    const blX = centerX + sinYaw * halfWidth;
    const blY = centerY;
    const blZ = centerZ - cosYaw * halfWidth;

    const brX = centerX + sinYaw * -halfWidth;
    const brY = centerY;
    const brZ = centerZ - cosYaw * -halfWidth;

    const halfMidWidth = MID_WIDTH * 0.5;
    const tlX = centerX + sinYaw * halfMidWidth;
    const tlY = centerY + height * 0.5;
    const tlZ = centerZ - cosYaw * halfMidWidth;

    const trX = centerX + sinYaw * -halfMidWidth;
    const trY = centerY + height * 0.5;
    const trZ = centerZ - cosYaw * -halfMidWidth;

    const tcX = centerX + sinTipBend * TIP_OFFSET;
    const tcY = centerY + height;
    const tcZ = centerZ - cosTipBend * TIP_OFFSET;

    // Positions
    positions[posIdx] = blX; positions[posIdx + 1] = blY; positions[posIdx + 2] = blZ;
    positions[posIdx + 3] = brX; positions[posIdx + 4] = brY; positions[posIdx + 5] = brZ;
    positions[posIdx + 6] = trX; positions[posIdx + 7] = trY; positions[posIdx + 8] = trZ;
    positions[posIdx + 9] = tlX; positions[posIdx + 10] = tlY; positions[posIdx + 11] = tlZ;
    positions[posIdx + 12] = tcX; positions[posIdx + 13] = tcY; positions[posIdx + 14] = tcZ;

    // UVs
    for (let i = 0; i < 5; i++) {
      uvs[uvIdx + i * 2] = uvX;
      uvs[uvIdx + i * 2 + 1] = uvY;
    }

    // Colors
    colors[colIdx] = 0; colors[colIdx + 1] = 0; colors[colIdx + 2] = 0;
    colors[colIdx + 3] = 0; colors[colIdx + 4] = 0; colors[colIdx + 5] = 0;
    colors[colIdx + 6] = 0.5; colors[colIdx + 7] = 0.5; colors[colIdx + 8] = 0.5;
    colors[colIdx + 9] = 0.5; colors[colIdx + 10] = 0.5; colors[colIdx + 11] = 0.5;
    colors[colIdx + 12] = 1.0; colors[colIdx + 13] = 1.0; colors[colIdx + 14] = 1.0;

    // Indices
    indices[indIdx] = vArrOffset;
    indices[indIdx + 1] = vArrOffset + 1;
    indices[indIdx + 2] = vArrOffset + 2;
    indices[indIdx + 3] = vArrOffset + 2;
    indices[indIdx + 4] = vArrOffset + 4;
    indices[indIdx + 5] = vArrOffset + 3;
    indices[indIdx + 6] = vArrOffset + 3;
    indices[indIdx + 7] = vArrOffset;
    indices[indIdx + 8] = vArrOffset + 2;
  }


}
