import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { DRACOLoader } from 'three/examples/jsm/loaders/DRACOLoader.js';
import { CURSOR_STATES, siteContent } from './siteData.js';
import { debugLog } from './debugger/debugLog.js';

import gsap from 'gsap';
import { createText } from './utils.js';


export class CursorController {
    constructor(renderer, texureLoaderInst, dummy) {
        this.renderer = renderer;

        this.isLoaded = false;
        this.experienceStarted = false;
        this.isFinished = false; // Added flag to manage the render loop

        this.scene = new THREE.Scene();
        this.camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.1, 10);
        this.camera.position.z = 1;

        this.activeScene = "";
        this.activeCamera;
        this.uiCamera;

        this.onClickCallback = null;
        this.onHoverCallback = null;

        this.beginText = dummy;

        this.raycaster = new THREE.Raycaster();
        this.mouse = new THREE.Vector2();
        this.clickableObjects = {};
        this.textureLoader = texureLoaderInst;

        //#region Cursor Data
        this.currentCursorState = CURSOR_STATES.IDLE;
        this.lockedOscillationTween = null;
        this.cursorTextures;
        this.customCursor;
        this.cursorMaterial;
        this.cursorScale = 0.06;

        this.initCursor();

        //#endregion

        this.bindEvents();
    }

    initCursor() {

        const onError = (error) => {
            console.error('A texture failed to load:', error);
            // You could implement fallback logic here
        };

        this.cursorTextures = {
            locked: this.textureLoader.load(siteContent.cursorTextures.locked, undefined, onError),
            idle: this.textureLoader.load(siteContent.cursorTextures.idle, undefined, onError),
            hover: this.textureLoader.load(siteContent.cursorTextures.hover, undefined, onError)
        };

        this.cursorMaterial = new THREE.SpriteMaterial({
            map: this.cursorTextures.idle, // Start in locked state
            depthTest: false,           // Render on top of everything
            depthWrite: false,
            transparent: true
        });

        this.customCursor = new THREE.Sprite(this.cursorMaterial);
        this.customCursor.scale.set(this.cursorScale, this.cursorScale, 1); // Adjust scale based on your scene/camera
        this.customCursor.renderOrder = 999;      // Guarantee it renders last (on top)

        this.scene.add(this.customCursor);
        //#endregion
    }

    bindEvents() {
        window.addEventListener('click', (event) => {
            debugLog("Cursor Mouse Click: " + event.clientX + ", " + event.clientY, "comic");

            this.mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
            this.mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

            this.raycaster.setFromCamera(this.mouse, this.activeCamera);

            // const intersects = this.raycaster.intersectObject(this.beginText);
            const intersects = this.raycaster.intersectObjects(this.clickableObjects[this.activeScene], true);

            if (intersects.length > 0) {
                debugLog("Clicked on object in scene: " + this.activeScene, "comic");
                if (this.onClickCallback) {
                    this.onClickCallback(intersects[0].object, this.mouse);
                }
            }
            else {
                if (this.activeScene === 'main') {
                    if (this.onClickCallback) {
                        this.onClickCallback(null, this.mouse);
                    }
                }
            }
        });

        window.addEventListener('mousemove', (event) => {

            this.mouse.x = (event.clientX / window.innerWidth) * 2 - 1;
            this.mouse.y = -(event.clientY / window.innerHeight) * 2 + 1;

            const aspect = window.innerWidth / window.innerHeight;
            this.customCursor.position.set(this.mouse.x * aspect, this.mouse.y, 0);

            if (this.currentCursorState === CURSOR_STATES.LOCKED)
                return;

            this.checkAndUpdateCursor();
        });

        window.addEventListener('mouseleave', () => {
            if (this.currentCursorState !== CURSOR_STATES.LOCKED) {
                this.setCursorState(CURSOR_STATES.IDLE);
            }
            if (this.onHoverCallback) {
                this.onHoverCallback(null);
            }
        });
    }

    resize(width, height) {
        const aspect = width / height;
        this.camera.left = -aspect;
        this.camera.right = aspect;
        this.camera.top = 1;
        this.camera.bottom = -1;
        this.camera.updateProjectionMatrix();
    }

    setScene(activeScene, activeCam, onClickCallback = null, onHoverCallback = null) {
        this.activeScene = activeScene;
        this.activeCamera = activeCam;
        this.onClickCallback = onClickCallback;
        this.onHoverCallback = onHoverCallback;
    }

    registerClickableObject(sceneId, object) {
        debugLog("registering clickable object: " + sceneId, "cursor");
        if (!this.clickableObjects[sceneId]) {
            this.clickableObjects[sceneId] = [];
        }
        this.clickableObjects[sceneId].push(object);
    }

    checkAndUpdateCursor() {
        this.raycaster.setFromCamera(this.mouse, this.activeCamera);

        // const intersects = this.raycaster.intersectObject(this.beginText);
        const intersects = this.raycaster.intersectObjects(this.clickableObjects[this.activeScene], true);

        if (intersects.length > 0) {

            this.setCursorState(CURSOR_STATES.HOVER);
            if (this.onHoverCallback) {
                this.onHoverCallback(intersects[0].object, this.mouse, intersects[0]);
            }
        }
        else {
            //check if on contact card button
            this.raycaster.setFromCamera(this.mouse, this.uiCamera);
            const uiIntersects = this.raycaster.intersectObjects(this.clickableObjects['contact'], true);
            if (this.activeScene === 'main')
                debugLog("ui check " + uiIntersects.length, "cursor");

            if (uiIntersects.length > 0) {
                this.setCursorState(CURSOR_STATES.HOVER);
                if (this.onHoverCallback) {
                    this.onHoverCallback(uiIntersects[0].object, this.mouse, uiIntersects[0]);
                }
            }
            else {
                this.setCursorState(CURSOR_STATES.IDLE);
                if (this.onHoverCallback) {
                    this.onHoverCallback(null);
                }
            }
        }
    }


    setCursorState(newState) {
        // return;
        if (this.currentCursorState === newState) return; // Prevent redundant updates

        // Kill oscillation tween when leaving locked state
        if (this.currentCursorState === CURSOR_STATES.LOCKED && newState !== CURSOR_STATES.LOCKED) {
            if (this.lockedOscillationTween) {
                this.lockedOscillationTween.kill();
                this.lockedOscillationTween = null;
            }
            this.customCursor.material.rotation = 0;
        }

        this.currentCursorState = newState;
        this.customCursor.material.map = this.cursorTextures[newState];

        if (newState === CURSOR_STATES.LOCKED) {
            this.customCursor.center.set(0.5, 0.5);
        }
        else if (newState === CURSOR_STATES.IDLE) {
            this.customCursor.center.set(0, 1);
        }
        else if (newState === CURSOR_STATES.HOVER) {
            this.customCursor.center.set(0.3, 1);
        }

        this.customCursor.material.needsUpdate = true;

        // Optional: Add a tiny GSAP pop animation when state changes
        gsap.fromTo(this.customCursor.scale,
            { x: this.cursorScale * 0.8, y: this.cursorScale * 0.8 },
            { x: this.cursorScale, y: this.cursorScale, duration: 0.3, ease: "back.out(1.7)" }
        );

        // Start oscillation when entering locked state
        if (newState === CURSOR_STATES.LOCKED) {
            // this.lockedOscillationTween = gsap.to(this.customCursor.material, {
            //     rotation: THREE.MathUtils.degToRad(90),
            //     duration: 0.6,
            //     ease: "sine.inOut",
            //     yoyo: true,
            //     repeat: -1,
            //     yoyoEase: "sine.inOut",
            // });

            this.lockedOscillationTween = gsap.to(this.customCursor.material, {
                rotation: THREE.MathUtils.degToRad(360),
                duration: 2,
                ease: "none",
                repeat: -1,
            });
        }
    }

    update(time) {
        // Use the new isFinished flag to know exactly when to stop rendering the overlay

        // const prevAutoClear = this.renderer.autoClear;
        this.renderer.autoClear = false;

        this.renderer.clearDepth();
        this.renderer.render(this.scene, this.camera);

        // this.renderer.autoClear = prevAutoClear;
    }

}