    render(time) {
        // This will be called from the main animation loop

        if (this.cardWrapper.visible) {

            if (this.contactCardPhotoMat && this.contactCardPhotoMat.uniforms) {
                this.contactCardPhotoMat.uniforms.iTime.value = time;
            }
            // this.myVine.update(time * 0.001); // Pass seconds
        }

        if (this.floatingButton.visible) {

            if (this.floatingButtonMat && this.floatingButtonMat.uniforms) {
                this.floatingButtonMat.uniforms.iTime.value = time;
            }
        }

        if (this.cardWrapper.visible || this.floatingButton.visible) {
            this.uiComposer.render();
        }
    }

    findButtonParent(object) {
        if (object.userData && object.userData.id) {
            return object;
        }
        if (object.parent) {
            return this.findButtonParent(object.parent);
        }
        return null;
    }

    handleButtonClick(id) {
        debugLog("ContactCard handleButtonClick for id: " + id, "cc");
        switch (id) {
            case 'contact_floating':
                this.show();
                break;
            case 'linkedin':
                window.open(siteContent.contactCard_linkedin.url, '_blank');
                break;
            case 'upwork':
                window.open(siteContent.contactCard_upwork.url, '_blank');
                break;
            default:
                console.log("No action defined for contact card button:", id);
        }
    }

    animateInFloatingButton() {
        // Called once the main experience is loaded
        debugLog("ContactCard animateInFloatingButton", "cc");
        this.floatTl.to(this.floatingButton.position, {
            y: this.targetFloatingY,
            duration: 1.5,
            ease: "back.out(1.5)",
            // delay: 1.0,
            onComplete: () => {
                debugLog("animate float in complete ", "cc");
                this.floatButtonGlitchTl.play();
                // this.floatButtonGlitchTl.restart();
            }
        });
        this.floatTl.play();
    }

    animateOutFloatingButton() {
        // Called once the main experience is loaded
        debugLog("ContactCard animateInFloatingButton", "cc");
        // this.floatTl.reverse();

        gsap.to(this.floatingButton.position, {
            y: this.fbStartPosY,
            duration: 1,
            ease: "power1.out",
            // delay: 1.0,
            onStart: () => {
                debugLog("animate float out started ", "cc");
                this.floatButtonGlitchTl.pause();
            }
        });
    }

    applyPeriodicGlitchEffect(material) {
        // Create a timeline that loops infinitely
        // repeatDelay is your "interval" between glitches (e.g., 3 seconds)
        const glitchTimeline = gsap.timeline({
            paused: true,
            repeat: -1,
            repeatDelay: 15
        });

        // Spike the glitch to 1.0 (or higher!) quickly
        glitchTimeline.to(material.uniforms.uGlitchIntensity, {
            value: 80, // How intense the glitch is
            duration: 0.1, // Very fast spike
            ease: "power4.in" // Accelerates into the glitch
        })
            // Instantly pull it back to 0 (normal)
            .to(material.uniforms.uGlitchIntensity, {
                value: 0.0,
                duration: 0.2, // slightly longer to recover
                ease: "bounce.out" // Gives it a slight mechanical "snap" back into place
            });

        return glitchTimeline;
    }



