        // Keep floating button anchored to bottom-left
        const padding = 120 * scaleFactor;
        this.floatingButton.position.x = -width / 2 + padding;
        this.targetFloatingY = -height / 2 + padding;
        this.fbStartPosY = -height + padding;
        this.floatingButton.position.z = 8;

        if (!this.isActive && this.floatingButton.position.y > -1000) {
            // Update its position immediately if it's already finished animating in
            this.floatingButton.position.y = this.targetFloatingY;
        }

        this.floatingButton.scale.set(scaleFactor, scaleFactor, 1);



        // #region Contact Card


        const contactCardY = 0;
        this.contactCardBorder.position.set(0, Math.round((this.contactCardSize.y / 2) * scaleFactor), 12);
        this.contactCardBorder.scale.set(1 * scaleFactor, 1 * scaleFactor, 1);
