    show() {
        debugLog("ContactCard show, active: " + this.isActive, "cc");
        if (this.isActive) return;
        this.animateOutFloatingButton();
        this.isActive = true;
        window.isContactCardActive = true; // Global flag to block scroll/clicks

        this.cardWrapper.visible = true;
        this.overlay.visible = true;

        gsap.to(this.overlay.material, { opacity: 0.8, duration: 0.4 });

        // Animate the card pop-in
        this.contactCardGroup.scale.set(0.1, 0.1, 0.1);
        gsap.to(this.contactCardGroup.scale, {
            x: 1, y: 1, z: 1,
            duration: 0.5,
            ease: "back.out(1.2)",
            onUpdate: () => {
                this.updateEmailElementPosition();
            },
            onComplete: () => {
                debugLog("card show complete ", "cc");
                this.ccPhotoGlitchTl?.play();
                this.updateEmailElementPosition();
                // this.floatButtonGlitchTl.restart();
            }
        });

        // this.myVine.grow(1.5);
    }

    hide() {
        debugLog("ContactCard hide, active: " + this.isActive, "cc");
        if (!this.isActive) return;
        this.animateInFloatingButton();
        this.isActive = false;
        window.isContactCardActive = false;

        gsap.to(this.overlay.material, { opacity: 0, duration: 0.3 });
        gsap.to(this.contactCardGroup.scale, {
            x: 0, y: 0, z: 0,
            duration: 0.3,
            ease: "power2.in",
            onStart: () => {
                this.emailElement.style.display = 'none';
            },
            onComplete: () => {
                this.cardWrapper.visible = false;
                this.ccPhotoGlitchTl?.pause();
            }
        });
    }

    updateEmailElementPosition() {
        if (!this.contactEmailText.textRenderInfo || !this.cardWrapper.visible) {
            this.emailElement.style.display = 'none';
            return;
        }

        const worldPos = new THREE.Vector3();
        // We need the world position of the text mesh
        this.contactEmailText.getWorldPosition(worldPos);

        const width = window.innerWidth;
        const height = window.innerHeight;

        // Project 3D point to 2D screen space
        worldPos.project(this.uiCamera);

        const screenX = (worldPos.x * 0.5 + 0.5) * width;
        const screenY = (-worldPos.y * 0.5 + 0.5) * height;

        // Get text dimensions to center the div
        const { blockBounds } = this.contactEmailText.textRenderInfo;
        const textWidth = (blockBounds[2] - blockBounds[0]) * this.contactCardGroup.scale.x;
        const textHeight = ((blockBounds[3] - blockBounds[1]) * this.contactCardGroup.scale.y) - 12; // Add some padding for easier clicking

        this.emailElement.style.display = 'block';
        this.emailElement.style.left = `${screenX - textWidth / 2}px`;
        this.emailElement.style.top = `${screenY - textHeight / 2}px`;
        this.emailElement.style.width = `${textWidth}px`;
        this.emailElement.style.height = `${textHeight}px`;
        this.emailElement.style.fontSize = `${FONT_SIZE.heading2 * this.contactCardGroup.scale.y}px`;
        this.emailElement.style.fontFamily = 'Newsreader, serif';
        this.emailElement.style.fontWeight = '500'; // medium
        this.emailElement.style.textAlign = 'center';
    }

    handleClick(mouse) {
        debugLog("ContactCard handleClick, active: " + this.isActive, "cc");

        this.raycaster.setFromCamera(mouse, this.uiCamera);
        const intersects = this.raycaster.intersectObjects(this.uiScene.children, true);

        if (this.isActive) {
            if (intersects.length > 0) {
                let clickedOnCard = false;
                for (const intersect of intersects) {
                    let current = intersect.object;
                    while (current) {
                        if (current === this.contactCardGroup) {
                            clickedOnCard = true;
                            break;
                        }
                        current = current.parent;
                    }
                    if (clickedOnCard) break;
                }

                if (!clickedOnCard) {
                    this.hide();
                    return true;
                }

                for (const intersect of intersects) {
                    const button = this.findButtonParent(intersect.object);
                    if (button) {
                        this.handleButtonClick(button.userData.id);
                        return true;
                    }
                }
            } else {
                this.hide();
            }
            return true;
        } else {
            if (intersects.length > 0) {
                for (const intersect of intersects) {
                    const button = this.findButtonParent(intersect.object);
                    if (button && button.userData.id === 'contact_floating') {
                        this.show();
                        return true;
                    }
                }
            }
        }
        return false;
    }
