import * as THREE from 'three';
import { Text, getSelectionRects } from 'troika-three-text'

import gsap from "gsap"
import { debugLog } from "../../../debugger/debugLog.js";

/**
 * @param {import("./sectionalAnimationManager.js").SectionalAnimationManager} animManager
 */
export default async function section1Forward
    (animManager) {

    debugLog("Section 1", "sec1_debug");

    const sectionDuration = 10;
    const butterflyPath = "paths/butterflySec1.json";
    const snakePath = "paths/snakeSec1.json";

    animManager.section1ForwardTl = gsap.timeline({ paused: animManager.typeSectional })


    const crescentValue = 9.8;

    // moon 
    animManager.section1ForwardTl
        .to(animManager.moonMaterial.uniforms.uTextureReveal, {
            value: 1,
            duration: 2,
            // ease: "power1.inOut"
        }, 0)
        .to(animManager.moonMaterial.uniforms.uPhaseStrength, {
            value: 1,
            duration: 2,
            // ease: "power1.inOut"
        }, '>')
        .to(animManager.moonPhasingData, {
            progress: crescentValue, // Animate from 0 to 1
            duration: 7,
            // ease: "power1.inOut",
            onUpdate: () => {
                // debugLog(`Moon Phase Progress: ${phasingData.progress.toFixed(2)} / ${phasingDuration.toFixed(2)} seconds`);
                animManager.moonMaterial.uniforms.uTime.value = animManager.moonPhasingData.progress; // One full rotation for the phase cycle

            },
            onStart: () => {
                debugLog("normal - moon start section 1 ", "sec1Alt_debug");
            }
        }, '<');



    const butterflyCurveId = await animManager.curveEditor.loadCurveFromPath(butterflyPath, "bfly-sec1-fwd");
    const butterflyCurve1 = animManager.curveEditor.curves[butterflyCurveId].curve3;

    debugLog("Butterfly Curve Loaded for Section 1 " + animManager.scaleFactor, "sec1_debug");
    let startPoint = butterflyCurve1.getPoint(0);
    startPoint = animManager.getResponsivePoint(butterflyCurve1, 0, 0, 0);
    let spawnPoint = startPoint.clone();
    spawnPoint.x = animManager.rightEdge; // start off-screen to the right
    spawnPoint.y += (50 * animManager.scaleFactorVec.y); // adjust for any vertical scaling
    animManager.butterfly.position.copy(spawnPoint);
    const butterflyFlightData = { progress: 0 };
    animManager.section1ForwardTl.to(butterflyFlightData, {
        progress: 1,
        duration: sectionDuration - 2,
        ease: "sine.in",
        // yoyo: true, // Go back and forth (optional)
        onUpdate: () => {
            // 1. Get the position on the curve
            debugLog("onupdate scalefactor " + animManager.scaleFactor, "sec1_debug");

            // let position = butterflyCurve1.getPoint(butterflyFlightData.progress);
            let position = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress, 0, 0);
            animManager.butterfly.position.copy(position);

            // 2. Handle Orientation (Make it face forward)
            // Look at a point slightly ahead in the future
            if (butterflyFlightData.progress + 0.01 < 1) {
                // let lookAtPosition = butterflyCurve1.getPoint(butterflyFlightData.progress + 0.01);
                let lookAtPosition = animManager.getResponsivePoint(butterflyCurve1, butterflyFlightData.progress + 0.01, 0, 0);
                animManager.butterfly.lookAt(lookAtPosition);
            }

        },
    }, 0);

    const snakeCurveId = await animManager.curveEditor.loadCurveFromPath(snakePath, "snk-sec1-fwd");
    const snakeCurve1 = animManager.curveEditor.curves[snakeCurveId].curve3;

    const snakeMotionData = { progress: 0 };
    animManager.section1ForwardTl.to(snakeMotionData, {
        progress: 1, // Animate from 0 to 1
        duration: sectionDuration - 2,
        ease: "back",
        //  ease: "power1.out", 
        // yoyo: true, // Go back and forth (optional)
        onUpdate: () => {
            // 1. Get the position on the curve
            // let position = snakeCurve1.getPoint(snakeMotionData.progress);//.multiplyScalar(animManager.scaleFactor);
            let position = animManager.getResponsivePoint(snakeCurve1, snakeMotionData.progress, 0, animManager.bgMeshOffest.y);
            // butterfly.position nh tv.copy(position);
            // position.add(animManager.bgMeshOffest);
            animManager.snake.update(position, snakeMotionData.progress);
        }
    }, 2);

    animManager.section1ForwardTl.to(animManager.quoteText.material, { opacity: 0, duration: sectionDuration, ease: 'power1.inOut' }, 0)
    animManager.section1ForwardTl.to(animManager.quoteTextEnglish.material, { opacity: 1, duration: sectionDuration, ease: 'power1.inOut' }, 0); // at the same time as the previous

    animManager.section1ForwardTl.call(() => {
        debugLog("showing comic ", "sec1_debug");
        animManager.setAboutContent(1);
    }, [], 8);

    // animManager.section1ForwardTl.to(animManager.quoteTextEnglish.material, { opacity: 0, duration: 1, ease: 'power1.inOut' });
    // animManager.section1ForwardTl.to(animManager.quoteGroup.position, { y:headerRightLastLetterPos.y, duration: 2,ease: 'power2.inOut'},'<');
    animManager.section1ForwardTl.addLabel("quoteMove", "<")

    // return "test";
    debugLog("Section 1 end " + startPoint, "sec_debug");
    return startPoint;
}